const repositoryRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');
const cppRuntime = resolveDependency(repositoryRoot, 'flight-cpp');
const cppRuntimeIncludeDirectories = collectCppRuntimeIncludeDirectories(cppRuntime.directory);
const cppToolchain = findCppCompilerToolchain();
const canCompileCpp = cppToolchain !== undefined && cppRuntimeIncludeDirectories.length > 0;

// The gate asks the question a passing emission does not: is what the backend wrote C++ at all? It costs
// about 3.3 seconds per fixture -- the target compiler parsing the runtime headers, not our own work -- so
// it is spent only on shapes an emitter change has touched, never on the suite's fixtures at large.
const cppSyntaxGate = createCppSyntaxGate(repositoryRoot);

// Returns the refusal rather than asserting a throw, so a probe that stops refusing leaves the
// caller comparing against a subject that was never produced instead of passing silently.
function captureBackendEmissionFailure(run: () => unknown) {
  try {
    run();
  } catch (error) {
    if (isBackendEmissionFailure(error)) return error;
    throw error;
  }
  throw new Error('expected C++ emission to refuse and it did not');
}

// A consumer module that returns something read from a provider package, which is the shape of every
// record whose declared type is not the one the value arrives as.
function emitRecordShapeConversionFiles(consumerSource: string) {
  const moduleResolution: CompilerModuleResolutionPlan = {
    edges: [
      {
        // The edge is the fallback for every importer rather than one module's, which is what a plan
        // written before the modules exist can say about a specifier only one module uses.
        importer: undefined as never,
        specifier: '@flighthq/types/readback',
        target: { packageName: '@flighthq/types', source: 'packages/types/src/readback.ts' },
      },
    ],
    schema: 'flight-compiler-module-resolution/1',
  };
  // Lowered together and with the resolution plan, because a provider function the consumer calls is an
  // external symbol until the plan binds it, and an unbound one refuses the module before any of this
  // reaches the emitter.
  const [provider, consumer] = lowerTypeScriptSources(
    [
      {
        packageName: '@flighthq/types',
        sourceFile: ts.createSourceFile(
          '/flight/packages/types/src/readback.ts',
          `export type BitmapReadbackBlockReason =
             'backend-not-installed' | 'empty-size' | 'no-canvas' | 'ok' | 'tainted-source';
           export type BitmapReadbackBackendReason =
             Exclude<BitmapReadbackBlockReason, 'backend-not-installed' | 'empty-size'>;
           export interface BitmapReadbackOutcome {
             readonly bitmap: string | null;
             readonly reason: BitmapReadbackBackendReason;
           }
           export interface HostBitmapReadbackCapability {
             readBitmap(source: string, width: number, height: number, mode: 'bitmap' | 'probe'): BitmapReadbackOutcome;
           }
           export function readBitmap(): BitmapReadbackOutcome { return { bitmap: null, reason: 'ok' }; }`,
          ts.ScriptTarget.Latest,
          true,
        ),
        upstreamDirectory: '/flight',
      },
      {
        packageName: '@flighthq/bitmap',
        sourceFile: ts.createSourceFile(
          '/flight/packages/bitmap/src/resolve.ts',
          consumerSource,
          ts.ScriptTarget.Latest,
          true,
        ),
        upstreamDirectory: '/flight',
      },
    ],
    moduleResolution,
  ).map((result) => result.module);
  const session = createCppCompilerBackend().createEmissionSession!({
    moduleResolution,
    modules: [consumer!, provider!],
    options: {
      packageTargets: {
        '@flighthq/bitmap': { includePrefix: 'flight/bitmap', namespace: 'flight::bitmap' },
        '@flighthq/types': { includePrefix: 'flight/types', namespace: 'flight::types' },
      },
      runtimeProfile: 'flight-cpp',
    },
  });
  return {
    consumer: session.emitModule(consumer!)[0]!,
    provider: session.emitModule(provider!)[0]!,
  };
}

function emitRecordShapeConversion(consumerSource: string): string {
  return emitRecordShapeConversionFiles(consumerSource).consumer.contents;
}

function emitCppModuleCppSession(
  results: readonly Readonly<{ module: IrModule }>[],
  moduleResolution: CompilerModuleResolutionPlan,
  index: number,
): string {
  return createCppCompilerBackend().createEmissionSession!({
    moduleResolution,
    modules: results.map((result) => result.module),
    options: { runtimeProfile: 'flight-cpp' },
  }).emitModule(results[index]!.module)[0]!.contents;
}

function lowerReexportedGenericCallableRowArgument() {
  const node = ts.createSourceFile(
    '/flight/packages/types/src/Node2D.ts',
    `export interface Node2D { x: number; }`,
    ts.ScriptTarget.Latest,
    true,
  );
  const transition = ts.createSourceFile(
    '/flight/packages/types/src/NodeInteractiveStateBinding.ts',
    `import type { Node2D } from '@flighthq/types/node';
     export interface TransitionRequest<N extends Node2D = Node2D> { readonly value: N; }
     export interface Transition<N extends Node2D = Node2D> {
       readonly run: (request: Readonly<TransitionRequest<N>>) => void;
     }`,
    ts.ScriptTarget.Latest,
    true,
  );
  const descriptor = ts.createSourceFile(
    '/flight/packages/types/src/GuiController.ts',
    `import type { Node2D } from '@flighthq/types/node';
     import type { Transition } from '@flighthq/types/transition';
     export type GuiTransitionDescriptor = Transition<Node2D>;`,
    ts.ScriptTarget.Latest,
    true,
  );
  const contract = ts.createSourceFile(
    '/flight/packages/types/src/contract.ts',
    `export type { Node2D } from '@flighthq/types/node';
     export type { GuiTransitionDescriptor } from '@flighthq/types/descriptor';`,
    ts.ScriptTarget.Latest,
    true,
  );
  const controller = ts.createSourceFile(
    '/flight/packages/gui/src/guiController.ts',
    `import type { GuiTransitionDescriptor, Node2D } from '@flighthq/types/contract';
     interface Runtime { transition: Readonly<GuiTransitionDescriptor> | null; }
     export function run(runtime: Runtime, target: Node2D | null): void {
       if (target === null || runtime.transition === null) return;
       runtime.transition.run({ value: target });
     }`,
    ts.ScriptTarget.Latest,
    true,
  );
  const moduleResolution: CompilerModuleResolutionPlan = {
    edges: [
      {
        specifier: '@flighthq/types/node',
        target: { packageName: '@flighthq/types', source: 'packages/types/src/Node2D.ts' },
      },
      {
        specifier: '@flighthq/types/transition',
        target: { packageName: '@flighthq/types', source: 'packages/types/src/NodeInteractiveStateBinding.ts' },
      },
      {
        specifier: '@flighthq/types/descriptor',
        target: { packageName: '@flighthq/types', source: 'packages/types/src/GuiController.ts' },
      },
      {
        specifier: '@flighthq/types/contract',
        target: { packageName: '@flighthq/types', source: 'packages/types/src/contract.ts' },
      },
      {
        specifier: '../../types/src/NodeInteractiveStateBinding.js',
        target: { packageName: '@flighthq/types', source: 'packages/types/src/NodeInteractiveStateBinding.ts' },
      },
    ],
    schema: 'flight-compiler-module-resolution/1',
  };
  const results = lowerTypeScriptSources(
    [
      { packageName: '@flighthq/types', sourceFile: node, upstreamDirectory: '/flight' },
      { packageName: '@flighthq/types', sourceFile: transition, upstreamDirectory: '/flight' },
      { packageName: '@flighthq/types', sourceFile: descriptor, upstreamDirectory: '/flight' },
      { packageName: '@flighthq/types', sourceFile: contract, upstreamDirectory: '/flight' },
      { packageName: '@flighthq/gui', sourceFile: controller, upstreamDirectory: '/flight' },
    ],
    moduleResolution,
  );
  return { moduleResolution, results };
}

function lower(file: string, source: string) {
  return lowerPackage('@flighthq/math', file, source);
}

// The plan a star re-export needs: one edge per module the chain names, under the specifier the module
// that wrote the import used, so a barrel resolves from the module that wrote it rather than from the
// module being emitted.
function cppStarResolution(
  edges: readonly Readonly<{ module: IrModule; specifier: string }>[],
): CompilerModuleResolutionPlan {
  return {
    edges: edges.map((edge) => ({
      specifier: edge.specifier,
      target: { packageName: edge.module.packageName, source: edge.module.source },
    })),
    schema: 'flight-compiler-module-resolution/1',
  };
}

function lowerPackage(packageName: string, file: string, source: string) {
  const packageDirectory = packageName.slice(packageName.lastIndexOf('/') + 1);
  const sourceFile = ts.createSourceFile(
    `/flight/packages/${packageDirectory}/src/${file}`,
    source,
    ts.ScriptTarget.Latest,
    true,
  );
  return lowerTypeScriptSource(sourceFile, {
    packageName,
    upstreamDirectory: '/flight',
  });
}

function lowerImportedClosedKeyStorageModules() {
  // Both consumers reach their types through the export-all contract barrel used by the SDK. The GUI
  // consumer mirrors guiTestHelper's non-null imported call result, computed runtime-key exclusion,
  // broad signal key, and callback assertion. The scene consumer mirrors flightDocumentText's
  // `states[phase] = state`.
  const moduleResolution: CompilerModuleResolutionPlan = {
    edges: [
      {
        specifier: './provider',
        target: { packageName: '@flighthq/closed-key', source: 'packages/closed-key/src/provider.ts' },
      },
      {
        specifier: './types',
        target: { packageName: '@flighthq/closed-key', source: 'packages/closed-key/src/types.ts' },
      },
      {
        specifier: '@flighthq/types/contract',
        target: { packageName: '@flighthq/closed-key', source: 'packages/closed-key/src/contract.ts' },
      },
    ],
    schema: 'flight-compiler-module-resolution/1',
  };
  const source = (file: string, text: string) => ({
    packageName: '@flighthq/closed-key',
    sourceFile: ts.createSourceFile(`/flight/packages/closed-key/src/${file}`, text, ts.ScriptTarget.Latest, true),
    upstreamDirectory: '/flight',
  });
  const results = lowerTypeScriptSources(
    [
      source(
        'types.ts',
        `export const EntityRuntimeKey = Symbol.for('EntityRuntime');
         export interface EntityRuntime { binding: object | null }
         export interface Entity { [EntityRuntimeKey]: EntityRuntime | undefined }
         export interface KeyboardEventData { altKey: boolean; key: string }
         export interface PointerEventData { altKey: boolean; x: number }
         export interface Signal<Listener> extends Entity { emit: Listener }
         export interface InteractionSignals extends Entity {
           onKeyDown: Signal<(data: Readonly<KeyboardEventData>) => void>;
           onPointerDown: Signal<(data: Readonly<PointerEventData>) => void>;
         }
         export type InteractionSignalName = Exclude<keyof InteractionSignals, typeof EntityRuntimeKey>;
         export interface InteractiveState { alpha?: number; visible?: boolean }
         export interface OptionalCounters { alpha?: number; beta?: number }
         export interface InteractiveStates {
           disabled: InteractiveState | null;
           hover: InteractiveState | null;
           pressed: InteractiveState | null;
         }
         export type InteractiveStatePhase = 'disabled' | 'hover' | 'pressed';`,
      ),
      source(
        'provider.ts',
        `import type { InteractionSignals } from './types';
         export function getInteractionSignals(target: object): InteractionSignals | null {
           void target;
           return null;
         }`,
      ),
      source(
        'gui.ts',
        `import { getInteractionSignals } from './provider';
         import type {
           InteractionSignalName,
           KeyboardEventData,
         } from '@flighthq/types/contract';
         export function emitKeyboard(target: object, name: InteractionSignalName): void {
           const data: KeyboardEventData = { altKey: false, key: 'Enter' };
           (getInteractionSignals(target)![name].emit as (data: Readonly<KeyboardEventData>) => void)(data);
         }`,
      ),
      source(
        'flightDocumentText.ts',
        `import type { InteractiveState, InteractiveStatePhase, InteractiveStates, OptionalCounters } from '@flighthq/types/contract';
         export function assignInteractiveState(
           states: InteractiveStates,
           phase: InteractiveStatePhase,
           state: InteractiveState,
         ): void {
           states[phase] = state;
         }
         export function readInteractiveState(
           state: InteractiveState,
           key: keyof InteractiveState,
         ): number | boolean | undefined {
           return state[key];
         }
         export function assignOptionalCounter(
           counters: OptionalCounters | null,
           key: keyof OptionalCounters,
           value: number,
         ): void {
           if (counters !== null) counters[key] = value;
         }`,
      ),
      source('contract.ts', "export * from './types';"),
    ],
    moduleResolution,
  );
  return { moduleResolution, results };
}

function lowerImportedTypeAssertionModules() {
  const moduleResolution: CompilerModuleResolutionPlan = {
    edges: [
      {
        specifier: '@flighthq/types/contract',
        target: { packageName: '@flighthq/types', source: 'packages/types/src/contract.ts' },
      },
    ],
    schema: 'flight-compiler-module-resolution/1',
  };
  const source = (packageName: string, file: string, text: string) => ({
    packageName,
    sourceFile: ts.createSourceFile(`/flight/packages/${file}`, text, ts.ScriptTarget.Latest, true),
    upstreamDirectory: '/flight',
  });
  const results = lowerTypeScriptSources(
    [
      source(
        '@flighthq/types',
        'types/src/contract.ts',
        `export interface EntityRuntime { binding: object | null }
         export const EntityRuntimeKey = Symbol.for('EntityRuntime');
         export interface Entity { [EntityRuntimeKey]: EntityRuntime | undefined }
         export interface RenderState extends Entity { pixelRatio: number }
         export interface RenderTargetDimensions { height: number; width: number }
         export interface AppRenderView<
           State extends RenderState = RenderState,
           Target extends RenderTargetDimensions = RenderTargetDimensions,
         > extends Entity { renderState: State; renderTarget: Target }
         export type AppRenderViewResize<
           State extends RenderState = RenderState,
           Target extends RenderTargetDimensions = RenderTargetDimensions,
         > = (state: State, target: Target, width: number, height: number) => void;
         export interface RenderStateRuntime extends EntityRuntime {
           currentFrameId: number;
           renderProxyMap: WeakMap<object, object>;
         }
         export interface CollisionAabb2D { maxX: number; minX: number }
         export interface CollisionCircle2D { radius: number; x: number }
         export type CollisionShape2D =
           | (CollisionAabb2D & { kind: 'aabb' })
           | (CollisionCircle2D & { kind: 'circle' });
         export function testImportedAabbPair(
           a: Readonly<CollisionAabb2D>,
           b: Readonly<CollisionAabb2D>,
         ): number { return a.maxX + b.minX; }
         export type ParticleFormatKind = 'One' | 'Two' | (string & Record<never, never>);`,
      ),
      source(
        '@flighthq/collision',
        'collision/src/collisionSupport2D.ts',
        `import type { CollisionAabb2D, CollisionShape2D } from '@flighthq/types/contract';
         export function support(shape: Readonly<CollisionShape2D>): number {
           const aabb = shape as CollisionAabb2D;
           return aabb.maxX;
         }`,
      ),
      source(
        '@flighthq/dialog',
        'dialog/src/fileDialog.ts',
        `import type { EntityRuntime } from '@flighthq/types/contract';
         interface FileDialogHandleRuntime extends EntityRuntime { operations: string | null }
         export function runtime(
           value: EntityRuntime | undefined,
         ): FileDialogHandleRuntime | undefined {
           return value as FileDialogHandleRuntime | undefined;
         }`,
      ),
      source(
        '@flighthq/particles-formats',
        'particles-formats/src/detect.ts',
        `import type { ParticleFormatKind } from '@flighthq/types/contract';
         export function detect(value: string | null): ParticleFormatKind | null {
           return value as ParticleFormatKind | null;
         }`,
      ),
      source(
        '@flighthq/app',
        'app/src/appRenderView.ts',
        `import type {
           AppRenderView,
           AppRenderViewResize,
           EntityRuntime,
           RenderState,
           RenderTargetDimensions,
         } from '@flighthq/types/contract';
         import { EntityRuntimeKey } from '@flighthq/types/contract';
         interface AppRenderViewRuntime<
           State extends RenderState = RenderState,
           Target extends RenderTargetDimensions = RenderTargetDimensions,
         > extends EntityRuntime {
           attached: boolean;
           resize: AppRenderViewResize<State, Target>;
           synchronize: () => void;
         }
         export function getAppRenderViewRuntime(
           view: AppRenderView,
         ): AppRenderViewRuntime<RenderState, RenderTargetDimensions> {
           return view[EntityRuntimeKey] as AppRenderViewRuntime<RenderState, RenderTargetDimensions>;
         }`,
      ),
      source(
        '@flighthq/render',
        'render/src/renderState.ts',
        `import type { RenderState, RenderStateRuntime } from '@flighthq/types/contract';
         import { EntityRuntimeKey } from '@flighthq/types/contract';
         export function getRenderStateRuntime(state: RenderState): RenderStateRuntime {
           return state[EntityRuntimeKey] as RenderStateRuntime;
         }`,
      ),
      source(
        '@flighthq/render',
        'render/src/concreteRenderState.ts',
        `import type { RenderStateRuntime } from '@flighthq/types/contract';
         import { EntityRuntimeKey } from '@flighthq/types/contract';
         interface RuntimeHolder { [EntityRuntimeKey]: RenderStateRuntime | undefined }
         export function getConcreteRuntime(state: RuntimeHolder): RenderStateRuntime {
           return state[EntityRuntimeKey] as RenderStateRuntime;
         }`,
      ),
      source(
        '@flighthq/collision',
        'collision/src/registerBuiltInCollisionPairTests2D.ts',
        `import { testImportedAabbPair } from '@flighthq/types/contract';
         import type { CollisionAabb2D, CollisionShape2D } from '@flighthq/types/contract';
         export function testRegisteredPair(
           a: Readonly<CollisionShape2D>,
           b: Readonly<CollisionShape2D>,
         ): number {
           return testImportedAabbPair(a as CollisionAabb2D, b as CollisionAabb2D);
         }`,
      ),
      source(
        '@flighthq/app',
        'app/src/typedAppRenderView.ts',
        `import type {
           AppRenderView,
           AppRenderViewResize,
           EntityRuntime,
           RenderState,
           RenderTargetDimensions,
         } from '@flighthq/types/contract';
         import { EntityRuntimeKey } from '@flighthq/types/contract';
         interface AppRenderViewRuntime<
           State extends RenderState = RenderState,
           Target extends RenderTargetDimensions = RenderTargetDimensions,
         > extends EntityRuntime {
           attached: boolean;
           resize: AppRenderViewResize<State, Target>;
           synchronize: () => void;
         }
         interface TypedAppRenderView<
           State extends RenderState = RenderState,
           Target extends RenderTargetDimensions = RenderTargetDimensions,
         > extends AppRenderView<State, Target> {
           [EntityRuntimeKey]: AppRenderViewRuntime<State, Target> | undefined;
         }
         export function createAppRenderViewRuntime<
           State extends RenderState,
           Target extends RenderTargetDimensions,
         >(
           resize: AppRenderViewResize<State, Target>,
           synchronize: () => void,
         ): AppRenderViewRuntime<State, Target> {
           return { attached: false, binding: null, resize, synchronize };
         }
         export function setAppRenderViewRuntime<
           State extends RenderState,
           Target extends RenderTargetDimensions,
         >(
           view: TypedAppRenderView<State, Target>,
           runtime: AppRenderViewRuntime<State, Target>,
         ): void {
           view[EntityRuntimeKey] = runtime;
         }
         export function getAppRenderViewRuntime<
           State extends RenderState,
           Target extends RenderTargetDimensions,
         >(
           view: TypedAppRenderView<State, Target>,
         ): AppRenderViewRuntime<State, Target> {
           return view[EntityRuntimeKey]!;
         }
         export function attachAppRenderView<
           State extends RenderState,
           Target extends RenderTargetDimensions,
         >(view: TypedAppRenderView<State, Target>): void {
           const runtime = getAppRenderViewRuntime(view);
           runtime.attached = true;
         }`,
      ),
    ],
    moduleResolution,
  );
  return { moduleResolution, results };
}

function lowerImportedSceneTypeAssertionModules() {
  const moduleResolution: CompilerModuleResolutionPlan = {
    edges: [
      {
        specifier: '@flighthq/types/contract',
        target: { packageName: '@flighthq/types', source: 'packages/types/src/contract.ts' },
      },
    ],
    schema: 'flight-compiler-module-resolution/1',
  };
  const source = (packageName: string, file: string, text: string) => ({
    packageName,
    sourceFile: ts.createSourceFile(`/flight/packages/${file}`, text, ts.ScriptTarget.Latest, true),
    upstreamDirectory: '/flight',
  });
  const results = lowerTypeScriptSources(
    [
      source(
        '@flighthq/types',
        'types/src/contract.ts',
        `export const EntityRuntimeKey = Symbol.for('EntityRuntime');
         export interface EntityRuntime { binding: object | null }
         export interface Entity { [EntityRuntimeKey]: EntityRuntime | undefined }
         export interface Scene2DRuntime extends EntityRuntime { scene2dSignals: object | null }
         export interface Scene2D extends Entity { root: Node2D }
         export interface NodeData extends Entity {}
         export interface NodeTraits { data: NodeData | null; kind: string }
         export interface Node<Traits extends object = NodeTraits> extends NodeTraits, Entity {}
         export type NodeAny = Node<any>;
         export interface Node2DData extends NodeData {}
         export interface Node2DTraits extends NodeTraits { data: Node2DData | null }
         export type Node2D = Node<Node2DTraits> & Node2DTraits;
         export interface SpriteData extends Node2DData { texture: object | null }
         export interface Sprite extends Node2D { data: SpriteData }
         export interface RenderCache extends Entity { cached: true }
         export type Renderable = NodeAny | RenderCache;
         export type ShapeCommandToken = string | number;
         export interface PbrExtension extends Entity { readonly kind: string }
         export interface TransmissionVolumePbrExtension extends PbrExtension {
           readonly kind: 'TransmissionVolumePbrExtension';
           transmission: number;
         }`,
      ),
      source(
        '@flighthq/scene2d',
        'scene2d/src/scene2d.ts',
        `import type { Scene2D, Scene2DRuntime } from '@flighthq/types/contract';
         import { EntityRuntimeKey } from '@flighthq/types/contract';
         export function getScene2DSignals(source: Readonly<Scene2D>): object | null {
           const runtime = source[EntityRuntimeKey] as Scene2DRuntime | undefined;
           return runtime?.scene2dSignals ?? null;
         }`,
      ),
      source(
        '@flighthq/scene2d',
        'scene2d/src/sceneKindUsage.ts',
        `import type { Node2D, ShapeCommandToken } from '@flighthq/types/contract';
         export function getCommands(node: Readonly<Node2D>): readonly ShapeCommandToken[] | undefined {
           return (node.data as Readonly<Partial<{ commands: readonly ShapeCommandToken[] }>> | null)?.commands;
         }`,
      ),
      source(
        '@flighthq/scene2d',
        'scene2d/src/sprite.ts',
        `import type { Renderable, Sprite } from '@flighthq/types/contract';
         export function getTexture(source: Renderable): object | null {
           return (source as Sprite).data.texture;
         }`,
      ),
      source(
        '@flighthq/scene3d-formats',
        'scene3d-formats/src/gltfTransmissionVolume.ts',
        `import type { PbrExtension, TransmissionVolumePbrExtension } from '@flighthq/types/contract';
         export function resolveTransmissionVolume(
           existing: PbrExtension | null,
         ): TransmissionVolumePbrExtension | null {
           if (existing === null) return null;
           return existing as TransmissionVolumePbrExtension;
         }`,
      ),
    ],
    moduleResolution,
  );
  return { moduleResolution, results };
}

