  it('keeps physics3d legacy hydration on its declared owner representation', () => {
    const { moduleResolution, results } = lowerImportedPhysics3DLegacyAssertionModules();
    const modules = results.map((result) => result.module);
    const session = createCppCompilerBackend().createEmissionSession!({
      moduleResolution,
      modules,
      options: { runtimeProfile: 'flight-cpp' },
    });
    const failures = modules
      .slice(1, 6)
      .map((module) => captureBackendEmissionFailure(() => session.emitModule(module)));
    const exact = session.emitModule(modules[6]!)[0]!.contents;

    // A reconstructed document cannot first occupy a current required-field owner and then regain the
    // optional cells of its legacy schema through `unknown`. The source boundary must retain one declared
    // serialized carrier until migration is complete. The one representation-equivalent assertion keeps
    // its exact owner, and a correctly typed optional carrier defaults its own cells directly.
    expect(results.flatMap((result) => result.diagnostics)).toEqual([]);
    for (const failure of failures) {
      expect(failure.rule).toBe('cpp-structural-assertion-owner-unproven');
      expect(failure.classification).toBe('source-portability');
      expect(failure.message).toContain(
        "whose optionality or value representation is not representation-equivalent to the source type's cells",
      );
      expect(failure.message).toContain('An assertion cannot add those cells');
      expect(failure.message).toContain('or change their representation');
      expect(failure.message).toContain('construct');
      expect(failure.message).toContain('with the asserted optionality and value representation');
      expect(failure.message).toContain('type the retaining slot and every accessor result as');
      expect(failure.message).toContain('will not reinterpret the owner, cast it, copy or materialize');
      expect(failure.message).toContain('or add side storage');
    }
    expect(failures[0]!.message).toContain('version');
    expect(failures[1]!.message).toContain('index, jointEvents and solver');
    expect(failures[2]!.message).toContain('maxCcdRotationSubsteps');
    expect(failures[3]!.message).toContain('colliders');
    expect(failures[4]!.message).toContain('colliderA and colliderB');
    expect(exact).toContain('return world;');
    expect(exact).toContain('contact->collider_a');
    expect(exact).toContain('contact->collider_b');
    expect(exact).not.toContain('flight::Any');
    expect(exact).not.toContain('static_cast');
    expect(exact).not.toContain('structural_ref_cast');
    expect(exact).not.toContain('make_ref');
    expect(exact).not.toContain('materialize');
    expect(exact).not.toContain('row_set');
  });

  it('keeps interactive state assertions on represented owners', () => {
    const common = `const EntityRuntimeKey = Symbol.for('EntityRuntime');
      interface EntityRuntime { binding: object | null }
      interface Entity { [EntityRuntimeKey]: EntityRuntime | undefined }
      declare const BindingBrand: unique symbol;
      interface NodeInteractiveStateBinding extends Entity { readonly [BindingBrand]: true }
      interface InteractiveRuntime extends EntityRuntime { disposed: boolean }
      interface NodeAny extends Entity { kind: string }
      type NodeInteractiveStateProperty = 'alpha' | 'scaleX' | 'scaleY' | 'visible' | 'x' | 'y';
      type NodeInteractiveStateTransitionValue = boolean | number;`;
    const results = [
      lower(
        'interactive-fresh.ts',
        `${common}
         export function create(runtime: InteractiveRuntime): NodeInteractiveStateBinding {
           return { [EntityRuntimeKey]: runtime } as unknown as NodeInteractiveStateBinding;
         }`,
      ),
      lower(
        'interactive-read.ts',
        `${common}
         export function read(node: NodeAny, property: NodeInteractiveStateProperty): unknown {
           const target = node as unknown as Record<NodeInteractiveStateProperty, unknown>;
           return target[property];
         }`,
      ),
      lower(
        'interactive-write.ts',
        `${common}
         export function write(
           node: NodeAny,
           property: NodeInteractiveStateProperty,
           value: NodeInteractiveStateTransitionValue,
         ): void {
           const target = node as unknown as Record<
             NodeInteractiveStateProperty,
             NodeInteractiveStateTransitionValue
           >;
           target[property] = value;
         }`,
      ),
      lower(
        'interactive-string-read.ts',
        `${common}
         export function read(node: NodeAny, property: NodeInteractiveStateProperty): unknown {
           return (node as unknown as Record<string, unknown>)[property];
         }`,
      ),
      lower(
        'interactive-exact-binding.ts',
        `${common}
         export function retain(binding: NodeInteractiveStateBinding): NodeInteractiveStateBinding {
           return binding as unknown as NodeInteractiveStateBinding;
         }`,
      ),
      lower(
        'interactive-exact-record.ts',
        `${common}
         export function retain(
           value: Record<NodeInteractiveStateProperty, NodeInteractiveStateTransitionValue>,
         ): Record<NodeInteractiveStateProperty, NodeInteractiveStateTransitionValue> {
           return value as unknown as Record<
             NodeInteractiveStateProperty,
             NodeInteractiveStateTransitionValue
           >;
         }`,
      ),
    ];
    const fresh = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(results[0]!.module, { runtimeProfile: 'flight-cpp' }),
    );
    const read = emitIrModuleCpp(results[1]!.module, { runtimeProfile: 'flight-cpp' }).contents;
    const write = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(results[2]!.module, { runtimeProfile: 'flight-cpp' }),
    );
    const stringRead = emitIrModuleCpp(results[3]!.module, { runtimeProfile: 'flight-cpp' }).contents;
    const exactBinding = emitIrModuleCpp(results[4]!.module, { runtimeProfile: 'flight-cpp' }).contents;
    const exactRecord = emitIrModuleCpp(results[5]!.module, { runtimeProfile: 'flight-cpp' }).contents;

    expect(results.flatMap((result) => result.diagnostics)).toEqual([]);
    expect(fresh.rule).toBe('cpp-erased-facet-reference-assertion-unrepresented');
    expect(fresh.classification).toBe('source-portability');
    expect(fresh.message).toContain('fresh object literal');
    expect(fresh.message).toContain('branded facet identity NodeInteractiveStateBinding');
    expect(fresh.message).toContain('flight::Ref<Entity> owner');
    expect(fresh.message).toContain('runtime slot');
    expect(fresh.message).toContain('will not reinterpret the literal, cast it, copy or materialize');
    expect(fresh.message).toContain('or add side storage');

    expect(read).toContain('flight::NamedProperties target');
    for (const output of [read, stringRead]) {
      expect(output).toContain('flight::named_properties(node)');
      expect(output).toContain('.get(property)');
      expect(output).not.toContain('flight::Record<NodeInteractiveStateProperty, flight::Any> target');
      expect(output).not.toContain('flight::Any::object(node)');
      expect(output).not.toContain('static_cast<flight::Record');
    }

    expect(write.rule).toBe('cpp-erased-record-assertion-unrepresented');
    expect(write.classification).toBe('source-portability');
    expect(write.message).toContain('flight::Ref<NodeAny>');
    expect(write.message).toContain('Record keyed storage are not representation-equivalent');
    expect(write.message).toContain('finite key union on a typed object');
    expect(write.message).toContain('dispatch to its declared fields');
    expect(write.message).toContain('will not cast between owners');
    expect(write.message).toContain('copy or materialize replacement keyed storage');
    expect(write.message).toContain('or add side storage');

    expect(exactBinding).toContain('return binding;');
    expect(exactRecord).toContain('return value;');
    for (const output of [exactBinding, exactRecord]) {
      expect(output).not.toContain('static_cast');
      expect(output).not.toContain('flight::Any::object');
      expect(output).not.toContain('make_ref');
      expect(output).not.toContain('materialize');
      expect(output).not.toContain('row_set');
    }
  });

  it('keeps reflective material operations on their represented owners', () => {
    const common = `const EntityRuntimeKey = Symbol.for('EntityRuntime');
      interface EntityRuntime { binding: object | null }
      interface Entity { [EntityRuntimeKey]: EntityRuntime | undefined }
      interface Material extends Entity { readonly kind: string; name?: string | null }`;
    const results = [
      lower(
        'material-equality.ts',
        `${common}
         export function equalsMaterial(a: Readonly<Material>, b: Readonly<Material>): boolean {
           if (a.kind !== b.kind) return false;
           const aFields = a as unknown as Record<string, unknown>;
           const bFields = b as unknown as Record<string, unknown>;
           const aKeys = Object.keys(aFields);
           const bKeys = Object.keys(bFields);
           if (aKeys.length !== bKeys.length) return false;
           for (const key of aKeys) {
             if (!Object.hasOwn(bFields, key)) return false;
             if (key === 'kind') continue;
             if (aFields[key] !== bFields[key]) return false;
           }
           return true;
         }`,
      ),
      lower(
        'material-copy.ts',
        `${common}
         export function copyMaterialFields(dst: Material, src: Readonly<Material>): void {
           const dstFields = dst as unknown as Record<string, unknown>;
           const srcFields = src as unknown as Record<string, unknown>;
           for (const key of Object.keys(srcFields)) dstFields[key] = srcFields[key];
         }`,
      ),
      lower(
        'material-source-read.ts',
        `${common}
         export function readMaterialField(src: Readonly<Material>, key: string): unknown {
           const srcFields = src as unknown as Record<string, unknown>;
           return srcFields[key];
         }`,
      ),
      lower(
        'material-exact-owner.ts',
        `${common}
         export function retain(material: Material): Material {
           return material as unknown as Material;
         }`,
      ),
      lower(
        'material-exact-record.ts',
        `export function retain(value: Record<string, unknown>): Record<string, unknown> {
           return value as unknown as Record<string, unknown>;
         }`,
      ),
    ];
    const equality = emitIrModuleCpp(results[0]!.module, { runtimeProfile: 'flight-cpp' }).contents;
    const copy = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(results[1]!.module, { runtimeProfile: 'flight-cpp' }),
    );
    const sourceRead = emitIrModuleCpp(results[2]!.module, { runtimeProfile: 'flight-cpp' }).contents;
    const exactOwner = emitIrModuleCpp(results[3]!.module, { runtimeProfile: 'flight-cpp' }).contents;
    const exactRecord = emitIrModuleCpp(results[4]!.module, { runtimeProfile: 'flight-cpp' }).contents;

    expect(results.flatMap((result) => result.diagnostics)).toEqual([]);
    expect(equality).toContain('flight::NamedProperties a_fields = flight::named_properties(a);');
    expect(equality).toContain('flight::NamedProperties b_fields = flight::named_properties(b);');
    expect(equality).toContain('b_fields.has(key)');
    expect(equality).toContain('a_fields.get(key)');
    expect(equality).toContain('b_fields.get(key)');
    expect(sourceRead).toContain('flight::NamedProperties src_fields = flight::named_properties(src);');
    expect(sourceRead).toContain('return src_fields.get(key);');
    for (const output of [equality, sourceRead]) {
      expect(output).not.toContain('flight::Record<flight::String, flight::Any>');
      expect(output).not.toContain('flight::Any::object');
      expect(output).not.toContain('static_cast<flight::Record');
      expect(output).not.toContain('materialize');
    }

    expect(copy.rule).toBe('cpp-named-properties-write-unsupported');
    expect(copy.classification).toBe('target-runtime');
    expect(copy.message).toContain('owner-preserving view of Material');
    expect(copy.message).toContain('Material remains the concrete object carrier and is not Record storage');
    expect(copy.message).toContain('NamedProperties::set(String, Any) contract');
    expect(copy.message).toContain('finite union of declared member names');
    expect(copy.message).toContain('will not cast between owners, copy into replacement storage');
    expect(copy.message).toContain('materialize a replacement owner');
    expect(copy.message).toContain('or add side storage');

    expect(exactOwner).toContain('return material;');
    expect(exactRecord).toContain('return value;');
    for (const output of [exactOwner, exactRecord]) {
      expect(output).not.toContain('static_cast');
      expect(output).not.toContain('flight::Any::object');
      expect(output).not.toContain('make_ref');
      expect(output).not.toContain('materialize');
      expect(output).not.toContain('row_set');
    }
  });

