  it('stores an optional property that also admits null through one plan, and refuses two value domains', () => {
    // The three real AnimationPlayer signal shapes from @flighthq/types. A `?` marker and a `null` in the
    // same type are two spellings of one three-state question, so the declaration and every crossing that
    // reads or writes it must ask the same authority. cloneAnimationPlayer and initializeAnimationPlayer
    // write null, enableAnimationPlayerSignals installs each owner behind `== null`, and the three emitters
    // collapse null/undefined with a nullish guard. That makes required-nullable the narrow source remedy,
    // but the backend still has to preserve the authored three states until the declaration changes.
    //
    // Lowered together and with the resolution plan, because the property's declared type lives in the
    // provider package: without the edge the consumer cannot see that `onFinished` admits absence at all.
    const fields = (onFinished: string): string =>
      `export interface AnimationClipEvent { readonly name: string }
       export interface Signal<T> { readonly id: number }
       export interface AnimationPlayer {
         readonly id: number;
         onEvent?: Signal<(event: Readonly<AnimationClipEvent>) => void> | null;
         ${onFinished}
         onLooped?: Signal<() => void> | null;
       }`;
    const consumerSource = (): string =>
      `import type { AnimationClipEvent, AnimationPlayer, Signal } from '@flighthq/types';
       function createSignal<T>(): Signal<T> { return { id: 1 }; }
       function emitSignal<T>(signal: Signal<T>): void { void signal.id; }
       export function initializeSignals(player: AnimationPlayer): void {
         player.onEvent = null;
         player.onFinished = null;
         player.onLooped = null;
       }
       export function enable(player: AnimationPlayer): void {
         if (player.onEvent == null) {
           player.onEvent = createSignal<(event: Readonly<AnimationClipEvent>) => void>();
         }
         if (player.onFinished == null) player.onFinished = createSignal<() => void>();
         if (player.onLooped == null) player.onLooped = createSignal<() => void>();
       }
       export function emitAll(player: AnimationPlayer): void {
         const eventSignal = player.onEvent;
         if (eventSignal != null) emitSignal(eventSignal);
         if (player.onFinished != null) emitSignal(player.onFinished);
         if (player.onLooped != null) emitSignal(player.onLooped);
       }
       export function finishedOr(
         player: AnimationPlayer,
         fallback: Signal<() => void>,
       ): Signal<() => void> {
         return player.onFinished ?? fallback;
       }`;
    const emit = (onFinished: string): string => {
      const [types, consumer] = lowerTypeScriptSources(
        [
          {
            packageName: '@flighthq/types',
            sourceFile: ts.createSourceFile(
              '/flight/packages/types/src/animationPlayer.ts',
              fields(onFinished),
              ts.ScriptTarget.Latest,
              true,
            ),
            upstreamDirectory: '/flight',
          },
          {
            packageName: '@flighthq/animation',
            sourceFile: ts.createSourceFile(
              '/flight/packages/animation/src/animationPlayer.ts',
              consumerSource(),
              ts.ScriptTarget.Latest,
              true,
            ),
            upstreamDirectory: '/flight',
          },
        ],
        {
          edges: [
            {
              importer: undefined as never,
              specifier: '@flighthq/types',
              target: { packageName: '@flighthq/types', source: 'packages/types/src/animationPlayer.ts' },
            },
          ],
          schema: 'flight-compiler-module-resolution/1',
        },
      );
      const session = createCppCompilerBackend().createEmissionSession!({
        moduleResolution: {
          edges: [
            {
              importer: undefined as never,
              specifier: '@flighthq/types',
              target: { packageName: '@flighthq/types', source: 'packages/types/src/animationPlayer.ts' },
            },
          ],
          schema: 'flight-compiler-module-resolution/1',
        },
        modules: [consumer!.module, types!.module],
        options: { runtimeProfile: 'flight-cpp' },
      });
      return session.emitModule(types!.module)[0]!.contents + session.emitModule(consumer!.module)[0]!.contents;
    };

    // One storage across all four crossings. The nested `std::optional<std::optional<...>>` this replaced
    // could not accept the write nor answer the test — g++ rejects the assignment outright.
    const both = emit('onFinished?: Signal<() => void> | null;');
    expect(both).toContain(
      'std::variant<flight::Ref<Signal<std::function<void()>>>, flight::Null, flight::Undefined> on_finished = std::variant<flight::Ref<Signal<std::function<void()>>>, flight::Null, flight::Undefined>{std::in_place_type<flight::Undefined>, flight::undefined};',
    );
    expect(both).toMatch(
      /std::variant<[^;\n]+flight::Null, flight::Undefined> on_event = std::variant<[^;\n]+flight::Null, flight::Undefined>\{std::in_place_type<flight::Undefined>, flight::undefined\};/u,
    );
    expect(both).toContain(
      'std::variant<flight::Ref<Signal<std::function<void()>>>, flight::Null, flight::Undefined> on_looped = std::variant<flight::Ref<Signal<std::function<void()>>>, flight::Null, flight::Undefined>{std::in_place_type<flight::Undefined>, flight::undefined};',
    );
    expect(both).not.toContain('std::optional<std::optional');
    expect(both).toContain('std::holds_alternative<flight::Null>(player->on_finished)');
    expect(both).toMatch(
      /const auto& coalesce_left = player->on_finished; if \(\(std::holds_alternative<flight::Null>\(coalesce_left\) \|\| std::holds_alternative<flight::Undefined>\(coalesce_left\)\)\) return fallback; return std::get<0>\(coalesce_left\);/u,
    );
    // The access unwraps through the plan rather than reading the property bare, which is what the
    // previous storage forced and what no `Ref<Signal<T>>` parameter can accept.
    expect(both).toContain(
      'emit_signal<std::function<void()>>(std::get<flight::Ref<flighthq_types::Signal<std::function<void()>>>>(player->on_finished))',
    );
    expect(both).not.toContain('reinterpret_cast');

    // The source-owned remedy uses the ordinary required-nullable carrier; it needs neither the undefined
    // alternative nor a new compiler representation.
    const required = emit('onFinished: Signal<() => void> | null;');
    expect(required).toContain('std::optional<flight::Ref<Signal<std::function<void()>>>> on_finished;');
    expect(required).toContain('(player->on_finished = std::nullopt);');

    // The storage-mismatch counterexample: two value domains leaves no single alternative a null-guard
    // proves, so the access still refuses rather than picking one of them.
    expect(() => emit('onFinished?: Signal<() => void> | number | null;')).toThrow(
      'present access requires optional C++ storage with one value domain',
    );
  });

  it('represents the fourteen GlMeshProgram mixed-absence fields without row materialization', () => {
    // These are the authoritative mixed-absence fields in @flighthq/types. Twelve are query-once caches:
    // undefined is unresolved, null is a completed missing-uniform lookup, and a location is present. The
    // two joint sampler slots differ at the source level: supporting factories eagerly write location/null,
    // non-supporting factories omit them, and no consumer resolves an omission. The backend nevertheless
    // has to preserve every authored tag until the source replaces each lazy cache with a closed state and
    // normalizes the redundant joint-slot sentinel. An omitted member must select Undefined rather than the
    // variant's first (location) alternative.
    const result = lower(
      'GlMeshProgram.ts',
      `export interface GlMeshProgram {
         locColorScale?: WebGLUniformLocation | null;
         locColorBias?: WebGLUniformLocation | null;
         locColorMatrix0?: WebGLUniformLocation | null;
         locColorMatrix1?: WebGLUniformLocation | null;
         locColorMatrix2?: WebGLUniformLocation | null;
         locColorMatrix3?: WebGLUniformLocation | null;
         locColorMatrixOffset?: WebGLUniformLocation | null;
         locObjectAlpha?: WebGLUniformLocation | null;
         locAlphaIsCoverage?: WebGLUniformLocation | null;
         locJointTexture?: WebGLUniformLocation | null;
         locInstancePalette?: WebGLUniformLocation | null;
         locInstanceColorPalette?: WebGLUniformLocation | null;
         locJointNormalTexture?: WebGLUniformLocation | null;
         locUvTransform?: WebGLUniformLocation | null;
         locModel: WebGLUniformLocation | null;
         locNormalMatrix: WebGLUniformLocation | null;
         locViewProjection: WebGLUniformLocation | null;
         program: WebGLProgram;
       }
       interface OptionalOnly { location?: WebGLUniformLocation }
       interface RequiredNullable { location: WebGLUniformLocation | null }
       export function create(program: WebGLProgram): GlMeshProgram {
         return { locModel: null, locNormalMatrix: null, locViewProjection: null, program };
       }
       export function state(value: GlMeshProgram): number {
         if (value.locColorScale === undefined) return 0;
         if (value.locColorScale === null) return 1;
         return 2;
       }
       export function omit(value: GlMeshProgram): void { value.locColorScale = undefined; }
       export function absent(value: GlMeshProgram): void { value.locColorScale = null; }
       export function present(value: GlMeshProgram, location: WebGLUniformLocation): void {
         value.locColorScale = location;
       }
       export function optionalOnly(): OptionalOnly { return {}; }
       export function requiredNull(): RequiredNullable { return { location: null }; }`,
    );
    const externalBindings = {
      bindings: [
        {
          headers: ['host/webgl.hpp'],
          nullability: 'non-null' as const,
          ownership: 'shared' as const,
          sourceName: 'WebGLProgram',
          space: 'type' as const,
          targetName: 'host::WebGlProgram',
        },
        {
          headers: ['host/webgl.hpp'],
          nullability: 'non-null' as const,
          ownership: 'shared' as const,
          sourceName: 'WebGLUniformLocation',
          space: 'type' as const,
          targetName: 'host::WebGlUniformLocation',
        },
      ],
      schema: 'flight-cpp-external-bindings/1' as const,
    };
    const missingBindings = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(result.module, { runtimeProfile: 'flight-cpp' }),
    );
    const contents = emitIrModuleCpp(result.module, { externalBindings, runtimeProfile: 'flight-cpp' }).contents;

    expect(result.diagnostics).toEqual([]);
    expect(missingBindings.rule).toBe('cpp-runtime-external-symbol-binding-incomplete');
    expect(missingBindings.classification).toBe('target-runtime');
    expect(missingBindings.message).toContain('missing: WebGLProgram[type], WebGLUniformLocation[type]');
    expect(missingBindings.message).toContain(
      'WebGL object handles WebGLProgram, WebGLUniformLocation are host-owned opaque identities',
    );
    expect(missingBindings.message).toContain('one externalBindings entry for each exact type-space source symbol');
    expect(missingBindings.message).toContain('stable target wrapper');
    expect(missingBindings.message).toContain('truthful ownership and nullability');
    expect(missingBindings.message).toContain('reuse that mapping in every module that carries the handle');
    expect(missingBindings.message).toContain('does not permit void-pointer or Any erasure');
    expect(missingBindings.message).toContain('native-pointer casts or reinterpretation');
    expect(missingBindings.message).toContain('copying or materializing replacement handles');
    expect(missingBindings.message).toContain('or side storage');
    const defaultedLocation =
      /std::variant<host::WebGlUniformLocation, flight::Null, flight::Undefined> loc_[a-z0-9_]+ = std::variant<host::WebGlUniformLocation, flight::Null, flight::Undefined>\{std::in_place_type<flight::Undefined>, flight::undefined\};/gu;
    expect(contents.match(defaultedLocation)).toHaveLength(14);
    expect(contents).toContain('std::holds_alternative<flight::Undefined>(value->loc_color_scale)');
    expect(contents).toContain('std::holds_alternative<flight::Null>(value->loc_color_scale)');
    expect(contents).toContain(
      '(value->loc_color_scale = std::variant<host::WebGlUniformLocation, flight::Null, flight::Undefined>{std::in_place_type<flight::Undefined>, flight::undefined})',
    );
    expect(contents).toContain(
      '(value->loc_color_scale = std::variant<host::WebGlUniformLocation, flight::Null, flight::Undefined>{std::in_place_type<flight::Null>, flight::null})',
    );
    expect(contents.match(/std::optional<host::WebGlUniformLocation> location;/gu)).toHaveLength(2);
    expect(contents).not.toContain('std::optional<host::WebGlUniformLocation> location =');
    expect(contents).not.toContain('flight::Any');
    expect(contents).not.toContain('reinterpret_cast');
    expect(contents).not.toContain('make_structural_ref');
    expect(contents).not.toContain('materialize_row');
  });

