  it('separates a mixed-absence guard member from an opaque adapter member', () => {
    // WgpuScene3DRuntime carries both families side by side, which is what the lane asked to separate. They
    // render differently and behave differently, so the control pins both rather than describing them: an
    // optional CALLABLE beside null and undefined is a dual-sentinel variant, while `unknown | null` is an
    // optional erased value -- and every consumer spelling of either lowers.
    const members = `export interface Scene3DLightsLike { readonly count: number }
export interface Scene3DMembers {
  readonly forwardLightSelectionGuard?: ((lights: Readonly<Scene3DLightsLike>) => void) | null;
  readonly skinningAdapter: unknown | null;
}`;

    const rendered = emitIrModuleCpp(lower('wgpu-scene3d.ts', members).module, {
      runtimeProfile: 'flight-cpp',
    }).contents;
    // mixed absence: the callable is one alternative beside BOTH sentinels
    expect(rendered).toContain('std::variant<std::function<void(');
    expect(rendered).toContain('flight::Null, flight::Undefined>');
    // opaque domain: one erased alternative beside null alone, because the source spells only `| null`
    expect(rendered).toContain('std::optional<flight::Any> skinning_adapter;');

    // The callable member's two consumer spellings ask the variant different questions: `?.` tests the
    // callable alternative it is about to use, while the `!= null` guard tests both sentinels.
    const optionalCall = emitIrModuleCpp(
      lower(
        'wgpu-guard-optional-call.ts',
        `${members}
export function use(r: Scene3DMembers, lights: Scene3DLightsLike): void { r.forwardLightSelectionGuard?.(lights); }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(optionalCall).toContain('holds_alternative<std::function<void(flight::StructuralRef');

    const guardedCall = emitIrModuleCpp(
      lower(
        'wgpu-guard-guarded-call.ts',
        `${members}
export function use(r: Scene3DMembers, lights: Scene3DLightsLike): void {
  if (r.forwardLightSelectionGuard != null) r.forwardLightSelectionGuard(lights);
}`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(guardedCall).toContain('holds_alternative<flight::Null>');
    expect(guardedCall).toContain('holds_alternative<flight::Undefined>');

    // The opaque member: reading it, writing it, and passing it on as the erased value it is.
    expect(
      emitIrModuleCpp(
        lower(
          'wgpu-adapter.ts',
          `${members}
export function read(r: Scene3DMembers): unknown { return r.skinningAdapter; }
export function write(r: Scene3DMembers, adapter: unknown): void { r.skinningAdapter = adapter; }
export function sink(value: unknown): void {}
export function pass(r: Scene3DMembers): void { if (r.skinningAdapter != null) sink(r.skinningAdapter); }`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ).contents,
    ).toContain('skinning_adapter');
  });

  it('names the value domain a weak-map member lookup needs', () => {
    // WgpuRenderState's sceneMeshUploadCache is `WeakMap<object, object> | null`, and the discriminator is
    // the VALUE type, not the optional member: a lookup through this member lowers when the value domain is
    // concrete, declared, or erased, and refuses only for the bare `object`. The refusal is otherwise
    // attributed to the compiler by default, so the control carries the remedy that makes the guidance
    // actionable.
    const member = (value: string) => `export interface S { readonly cache: WeakMap<object, ${value}> }`;
    const read = (value: string) => `${member(value)}
export function read(s: S, key: object): unknown { return s.cache.get(key); }`;

    // Every domain that lowers, including the erased one -- so the remedy is not "add erasure", it is "name
    // what the cache holds".
    for (const [file, value] of [
      ['weak-map-string.ts', 'string'],
      ['weak-map-entry.ts', 'Entry'],
      ['weak-map-unknown.ts', 'unknown'],
    ] as const) {
      const source =
        value === 'Entry'
          ? `export interface Entry { readonly version: number }
${member(value)}
export function read(s: S, key: object): Entry | undefined { return s.cache.get(key); }`
          : read(value);
      expect(emitIrModuleCpp(lower(file, source).module, { runtimeProfile: 'flight-cpp' }).contents).toContain('get(');
    }

    // The bare object value: refused, and the rule that answers is not one this lane should move, because it
    // is shared with every other missing-expression-type site. The control records it rather than pinning a
    // classification the declaration's ownership argues against.
    const bare = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(
        lower(
          'weak-map-object.ts',
          `${member('object')}
export function read(s: S, key: object): object | undefined { return s.cache.get(key); }`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ),
    );
    expect(bare.rule).toContain('cpp-contextual-union-missing-expression-type');
    expect(bare.classification).toBe('compiler-restriction');
  });

  it('documents the representation an opaque result payload arm already has', () => {
    // Tray.ts carries ~22 failed-outcome arms shaped `{ readonly error?: unknown; readonly outcome: '...' }`.
    // The opaque payload is NOT a gap: `unknown` is represented by the runtime's erased dynamic value, and
    // the whole union lowers. This pins that so a later "replace the opaque arm" reading of the report has
    // the representation in front of it, and pins the one refusal these shapes DO produce -- an unguarded
    // discriminant read on the generic result -- which belongs to a different rule.
    const arms = `export type TrayCreateCapabilityResult =
  | { readonly outcome: 'created' }
  | { readonly error?: unknown; readonly outcome: 'runtime-api-unavailable' }
  | { readonly error?: unknown; readonly outcome: 'invalid-icon' }
  | { readonly error?: unknown; readonly outcome: 'tray-create-failed' };`;

    const emitted = emitIrModuleCpp(lower('tray-result.ts', arms).module, { runtimeProfile: 'flight-cpp' }).contents;
    expect(emitted).toContain('std::optional<flight::Any> error;');
    expect(emitted).toContain('flight::String outcome;');

    // Both readings a consumer writes lower: narrowed by the discriminant, and the payload passed on as the
    // erased value it is.
    expect(
      emitIrModuleCpp(
        lower(
          'tray-consumer.ts',
          `${arms}
export function read(result: TrayCreateCapabilityResult): unknown {
  if (result.outcome === 'tray-create-failed') return result.error;
  return null;
}`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ).contents,
    ).toContain('return std::get<0>(result)->error;');

    // The file's generic result composes the arms with Entity and Exclude, and reading its discriminant
    // WITHOUT a guard is the one refusal in these shapes -- a union-member access rule, not an opaque-domain
    // one.
    const generic = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(
        lower(
          'tray-generic.ts',
          `export interface Entity { readonly id: number }
export interface TrayIcon { readonly path: string }
${arms}
export type TrayCreateResult<Tray extends TrayIcon = TrayIcon> =
  | (Entity & { readonly outcome: 'created'; readonly tray: Tray })
  | (Entity & Exclude<TrayCreateCapabilityResult, { readonly outcome: 'created' }>);
export function label<T extends TrayIcon>(result: TrayCreateResult<T>): string { return result.outcome; }`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ),
    );
    expect(generic.rule).toBe('cpp-union-member-access-unguarded');
    expect(generic.classification).toBe('source-portability');
  });

  it('pins the signals connection site and the container shape that replaces it', () => {
    // connection.ts asserts a connection into a scope whose element type is the WIDEST slot signature --
    // "the cast is the variance of that container, not a claim about this connection", as its own comment
    // says. The rule and both of its named rewrites are covered further up; what this adds is the exact
    // expression, because the site is a push into a heterogeneous container rather than a widening return,
    // and the container is what the rewrite has to change.
    const signals = `interface Signal<T extends (...args: any[]) => void> { emit: T }
interface SignalConnection<T extends (...args: any[]) => void> {
  connected: boolean;
  paused: boolean;
  signal: Signal<T>;
  slot: T;
}
interface SignalScope { connections: SignalConnection<(...args: any[]) => void>[] }`;

    const pushed = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(
        lower(
          'connection.ts',
          `${signals}
export function connectSignalTracked<T extends (...args: any[]) => void>(
  signal: Signal<T>,
  slot: T,
  scope?: SignalScope,
): SignalConnection<T> {
  const connection: SignalConnection<T> = { connected: true, paused: false, signal, slot };
  scope?.connections.push(connection as unknown as SignalConnection<(...args: any[]) => void>);
  return connection;
}`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ),
    );
    expect(pushed.rule).toBe('cpp-generic-owner-argument-assertion-unproven');
    expect(pushed.classification).toBe('source-portability');
    expect(pushed.message).toContain('store an operation closure that captures the exact owner');

    // The rewrite that fits this site: the scope keeps what it actually needs from the connection -- one
    // closed operation per entry -- and the connection keeps its own instantiation.
    expect(
      emitIrModuleCpp(
        lower(
          'connection-closure.ts',
          `${signals}
interface SignalScope2 { disconnectors: (() => void)[] }
export function connectSignalTracked2<T extends (...args: any[]) => void>(
  signal: Signal<T>,
  slot: T,
  scope?: SignalScope2,
): SignalConnection<T> {
  const connection: SignalConnection<T> = { connected: true, paused: false, signal, slot };
  scope?.disconnectors.push(() => { connection.connected = false; });
  return connection;
}`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ).contents,
    ).toContain('disconnectors');
  });

  // HostVideo.ts's opaque-value-domain finding. Its one opaque value domain is the stream handle the host
  // adapter accepts -- `attachStream?(stream: unknown)` -- and that parameter is arbitrary by declaration,
  // so it lowers to flight::Any and needs no guidance. The module's actual blockers are host ownership:
  // AbortSignal (a lifetime identity) and Blob (a binary object identity), both of which already carry
  // remediation prose. The control asserts the refusal, then binds exactly those two and shows the arbitrary
  // parameter surviving as flight::Any rather than being narrowed or copied.
  it('classifies the host video stream parameter as arbitrary data already carried', () => {
    const result = lower(
      'HostVideo.ts',
      `export interface HostVideoCapability {
         attachStream?(stream: unknown): string | null;
         canPlayType(mimeType: string): boolean;
         createObjectUrl?(data: Blob): string;
         loadUrl?(url: string, signal?: AbortSignal): Promise<string>;
       }`,
    );
    const failure = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(result.module, { runtimeProfile: 'flight-cpp' }),
    );
    expect(result.diagnostics).toEqual([]);
    expect(failure.rule).toBe('cpp-runtime-external-symbol-binding-incomplete');
    expect(failure.classification).toBe('target-runtime');
    expect(failure.message).toContain('missing: AbortSignal[type], Blob[type]');

    const contents = emitIrModuleCpp(result.module, {
      externalBindings: {
        bindings: [
          {
            headers: ['host/abort.hpp'],
            nullability: 'non-null' as const,
            ownership: 'shared' as const,
            sourceName: 'AbortSignal',
            space: 'type' as const,
            targetName: 'host::AbortSignal',
          },
          {
            headers: ['host/blob.hpp'],
            nullability: 'non-null' as const,
            ownership: 'shared' as const,
            sourceName: 'Blob',
            space: 'type' as const,
            targetName: 'host::Blob',
          },
        ],
        schema: 'flight-cpp-external-bindings/1' as const,
      },
      runtimeProfile: 'flight-cpp',
    }).contents;
    // The stream handle stays the erased carrier it was declared as, so the host adapter may accept any
    // stream the platform hands it without the compiler inventing a narrower type or copying it through one.
    expect(contents).toContain(
      'std::optional<std::function<std::optional<flight::String>(flight::Any)>> attach_stream;',
    );
  });

  // Where the dependency gate lives, and a guard against moving it.
  //
  // Emission is per-module: the session emits each module's own text without consulting that module's
  // dependencies, so a consumer whose imported alias refused for an unbound host symbol still produces text
  // naming that symbol. That text is not output. `compileTypeScriptPackageGraph` runs
  // `propagateCompilerPackageGraphRefusals` before it decides what to emit, marks the importer
  // `dependency-refused`, clears the files it had already produced, and filters refused records out of the
  // final file set, so nothing a refused dependency blocked ever reaches a caller. That gate is contracted
  // (`dependency-refused` in the package-compilation contract) and already pinned by
  // 'records every refused dependency that blocked a module' in compiler-orchestration and by
  // 'counts a refused dependency as a cascade rather than as the importing module finding' in
  // compiler-command-line.
  //
  // This control holds that boundary: the per-module emitter must NOT grow its own dependency walk, because
  // that would duplicate the orchestration gate and leave two places deciding whether a module may be emitted.
  it('keeps the dependency gate in orchestration rather than in the per-module emitter', () => {
    const moduleResolution: CompilerModuleResolutionPlan = {
      edges: [
        {
          specifier: './alias',
          target: { packageName: '@flighthq/types', source: 'packages/types/src/alias.ts' },
        },
      ],
      schema: 'flight-compiler-module-resolution/1',
    };
    const source = (file: string, body: string) => ({
      packageName: '@flighthq/types',
      sourceFile: ts.createSourceFile(`/flight/packages/types/src/${file}`, body, ts.ScriptTarget.Latest, true),
      upstreamDirectory: '/flight',
    });
    const results = lowerTypeScriptSources(
      [
        source('alias.ts', 'export type Handle = CanvasImageSource;'),
        source(
          'consumer.ts',
          `import type { Handle } from './alias';
           export interface C { attach?(stream: unknown): Handle | null; play?(element: Handle): void; }`,
        ),
      ],
      moduleResolution,
    );
    const session = createCppCompilerBackend().createEmissionSession!({
      moduleResolution,
      modules: results.map((result) => result.module),
      options: { runtimeProfile: 'flight-cpp' },
    });
    const alias = results.find((result) => result.module.source.endsWith('alias.ts'))!;
    const consumer = results.find((result) => result.module.source.endsWith('consumer.ts'))!;

    const aliasFailure = captureBackendEmissionFailure(() => session.emitModule(alias.module));
    expect(aliasFailure.rule).toBe('cpp-runtime-external-symbol-binding-incomplete');
    expect(aliasFailure.message).toContain('missing: CanvasImageSource[type]');

    const contents = session.emitModule(consumer.module)[0]!.contents;
    // The per-module session emits anyway -- which is exactly why the gate belongs one layer up.
    expect(contents).toContain('#include "alias.hpp"');
    // The unbound symbol is written raw into the signature, and the alias name is used with no declaration.
    expect(contents).toContain('std::optional<std::function<std::optional<CanvasImageSource>(flight::Any)>> attach;');
    expect(contents).toContain('std::optional<std::function<void(flight::Ref<flighthq_types::Handle>)>> play;');
    expect(contents).not.toContain('using CanvasImageSource');
  });

  // throttle.ts's first emitted refusal is one target-runtime handle family. Both debounce and throttle store
  // the exact handle returned by setTimeout in independent nullable local slots; replacement and cleanup pass
  // that same value to clearTimeout before nulling the slot. Once that profile gap is supplied, the module's
  // separate source-owned gap becomes visible: both handlers buffer an open dependent argument pack in any[].
  it('classifies the signal throttle timers as one target-runtime handle family', () => {
    const result = lower(
      'throttle.ts',
      `interface Signal<T extends (...args: any[]) => void> { readonly marker?: T }
       interface SignalThrottleOptions { leading?: boolean; trailing?: boolean }
       interface ThrottleTimerIdentity { readonly timer: timers.global.NodeJS.Timeout | null }
       function connectSignal<T extends (...args: any[]) => void>(source: Signal<T>, slot: T): void {
         void source;
         void slot;
       }
       function disconnectSignal<T extends (...args: any[]) => void>(source: Signal<T>, slot: T): void {
         void source;
         void slot;
       }
       export function connectSignalDebounced<T extends (...args: any[]) => void>(
         source: Signal<T>,
         delayMs: number,
         slot: T,
         options?: Readonly<SignalThrottleOptions>,
       ): () => void {
         const leading = options?.leading ?? false;
         const trailing = options?.trailing ?? true;
         let timer: ReturnType<typeof setTimeout> | null = null;
         let lastArgs: any[] | null = null;
         let leadingFired = false;
         const clearTimer = () => {
           if (timer !== null) {
             clearTimeout(timer);
             timer = null;
           }
         };
         const handler = ((...args: any[]) => {
           lastArgs = args;
           if (leading && timer === null && !leadingFired) {
             leadingFired = true;
             slot(...args);
           }
           clearTimer();
           timer = setTimeout(() => {
             timer = null;
             leadingFired = false;
             if (trailing && lastArgs !== null) {
               slot(...lastArgs);
               lastArgs = null;
             }
           }, delayMs);
         }) as T;
         connectSignal(source, handler);
         return () => {
           disconnectSignal(source, handler);
           clearTimer();
         };
       }
       export function connectSignalThrottled<T extends (...args: any[]) => void>(
         source: Signal<T>,
         intervalMs: number,
         slot: T,
         options?: Readonly<SignalThrottleOptions>,
       ): () => void {
         const leading = options?.leading ?? true;
         const trailing = options?.trailing ?? true;
         let lastFiredAt = -Infinity;
         let trailingTimer: ReturnType<typeof setTimeout> | null = null;
         let lastArgs: any[] | null = null;
         const clearTrailing = () => {
           if (trailingTimer !== null) {
             clearTimeout(trailingTimer);
             trailingTimer = null;
           }
         };
         const scheduleTrailing = (delay: number) => {
           trailingTimer = setTimeout(() => {
             lastFiredAt = Date.now();
             trailingTimer = null;
             slot(...lastArgs!);
             lastArgs = null;
           }, delay);
         };
         const handler = ((...args: any[]) => {
           const now = Date.now();
           const remaining = intervalMs - (now - lastFiredAt);
           if (remaining <= 0 || remaining > intervalMs) {
             clearTrailing();
             lastFiredAt = now;
             if (leading) {
               slot(...args);
             } else if (trailing) {
               lastArgs = args;
               scheduleTrailing(intervalMs);
             }
           } else if (trailing) {
             clearTrailing();
             lastArgs = args;
             scheduleTrailing(remaining);
           }
         }) as T;
         connectSignal(source, handler);
         return () => {
           disconnectSignal(source, handler);
           clearTrailing();
         };
       }`,
    );
    const failure = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(result.module, { runtimeProfile: 'flight-cpp' }),
    );

    expect(result.diagnostics).toEqual([]);
    expect(failure.rule).toBe('cpp-runtime-external-symbol-binding-incomplete');
    expect(failure.classification).toBe('target-runtime');
    expect(failure.message).toContain(
      'missing: clearTimeout[value], setTimeout[value], timers.global.NodeJS.Timeout[type]',
    );
    expect(failure.message).toContain(
      'timers.global.NodeJS.Timeout is a target-runtime scheduled-task handle identity',
    );
    expect(failure.message).toContain(
      'preserve the same handle from ReturnType<typeof setInterval> or ReturnType<typeof setTimeout>',
    );
    expect(failure.message).toContain('through nullable stored state to the matching clearInterval or clearTimeout');
    expect(failure.message).toContain(
      'give each scheduling binding a callResultType that names the same handle carrier',
    );

    // These are exactly the three missing runtime identities. The scheduled-task owner is one value carrier:
    // setTimeout produces it, each nullable slot retains it, and clearTimeout consumes that same value.
    const externalBindings = {
      bindings: [
        {
          headers: ['host/timer.hpp'],
          nullability: 'non-null' as const,
          ownership: 'value' as const,
          sourceName: 'clearTimeout',
          space: 'value' as const,
          targetName: 'host::clear_timeout',
        },
        {
          callResultType: 'host::TimerHandle',
          headers: ['host/timer.hpp'],
          nullability: 'non-null' as const,
          ownership: 'value' as const,
          sourceName: 'setTimeout',
          space: 'value' as const,
          targetName: 'host::set_timeout',
        },
        {
          headers: ['host/timer.hpp'],
          nullability: 'non-null' as const,
          ownership: 'value' as const,
          sourceName: 'timers.global.NodeJS.Timeout',
          space: 'type' as const,
          targetName: 'host::TimerHandle',
        },
      ],
      schema: 'flight-cpp-external-bindings/1' as const,
    };
    const sourceFailure = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(result.module, { externalBindings, runtimeProfile: 'flight-cpp' }),
    );
    expect(sourceFailure.rule).toBe('cpp-dependent-parameter-pack-nonterminal-use');
    expect(sourceFailure.classification).toBe('source-portability');
    expect(sourceFailure.message).toContain('cannot be named as storage');
    expect(sourceFailure.message).toContain('source declares the buffer as an array of `any`');
    expect(sourceFailure.message).toContain('parameterize the connector over the payload type');
    expect(sourceFailure.message).toContain('forwards a computed value rather than the source arguments');

    // A single typed payload needs no erased argument buffer: each scheduled closure retains that exact value.
    // With the same timer profile this source emits, proving the runtime and source classifications are distinct.
    const portable = lower(
      'throttle-payload.ts',
      `export function createDebouncedPayload<Payload>(
         delayMs: number,
         slot: (payload: Payload) => void,
       ): (payload: Payload) => void {
         let timer: ReturnType<typeof setTimeout> | null = null;
         return (payload: Payload): void => {
           if (timer !== null) clearTimeout(timer);
           timer = setTimeout(() => {
             timer = null;
             slot(payload);
           }, delayMs);
         };
       }`,
    );
    const contents = emitIrModuleCpp(portable.module, { externalBindings, runtimeProfile: 'flight-cpp' }).contents;
    expect(portable.diagnostics).toEqual([]);
    expect(contents).toContain('flight::make_binding_cell(std::optional<host::TimerHandle>');
    expect(contents).toContain('host::set_timeout');
    expect(contents).toContain('host::clear_timeout');
    expect(contents).not.toContain('flight::Any');
    expect(contents).not.toContain('reinterpret_cast');
    expect(contents).not.toContain('materialize');
  });
  // The guiController erased cell, traced and pinned. Its exact shape is a symbol-keyed object literal
  // asserted through `unknown` to a generic owner -- `{ [EntityRuntimeKey]: runtime } as unknown as
  // Controller` in @flighthq/gui/src/guiController.ts:76, and the identical spelling in
  // @flighthq/interaction/src/nodeInteractiveStateBinding.ts:82.
  //
  // Isolated, the cell DROPS the symbol-keyed member in every spelling: the literal alone emits an empty
  // braced init, and either cast emits an empty construction of the target. `runtime` never reaches storage,
  // so a later read of the slot the source installed finds nothing. The read side is emitted faithfully --
  // it names the member -- which is what makes the pair incoherent rather than merely unlowered.
  //
  // LATENT, NOT LIVE, and that is the reason this is pinned rather than escalated as urgent: every module in
  // the SDK that spells the cell this way already refuses earlier for an independent reason, so no emitted
  // header carries the drop today. The seven sites and their families at the time of tracing:
  //   guiController.ts family 2 (contextual union conversion), nodeInteractiveStateBinding.ts and node.ts
  //   family 30 (Partial<T> shape), clone.ts family 8 (structural-row projection), tray.ts,
  //   glScene3DRuntime.ts and glVelocity.ts family 0 (binding incomplete), wgpuScene3DRuntime.ts family 6.
  // If any of those unblocks, this control records what the cell would then emit.
  it('pins the erased runtime cell as a latent silent drop, with a faithful read beside it', () => {
    const contract = `export const EntityRuntimeKey = Symbol.for('EntityRuntime');
       export interface EntityRuntime { binding: object | null }
       export interface Entity { [EntityRuntimeKey]: EntityRuntime | undefined }
       export interface GuiControllerRuntime extends EntityRuntime { disposed: boolean }`;

    // The literal alone: the member is dropped and the type position falls back to `auto`.
    expect(
      emitIrModuleCpp(
        lower(
          'cell-literal.ts',
          `${contract}
           export function make<Runtime extends GuiControllerRuntime>(runtime: Runtime): Entity {
             const controller = { [EntityRuntimeKey]: runtime };
             return controller;
           }`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ).contents,
    ).toContain('auto controller = {};');

    // The real spelling: an empty construction of the owner, with the runtime argument unused.
    const doubleCast = emitIrModuleCpp(
      lower(
        'cell-double-cast.ts',
        `${contract}
         export function make<Controller extends Entity, Runtime extends GuiControllerRuntime>(
           runtime: Runtime,
         ): Controller {
           const controller = { [EntityRuntimeKey]: runtime } as unknown as Controller;
           return controller;
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(doubleCast).toContain('Controller controller = static_cast<Controller>({});');
    // The cell is constructed empty: no member write ever happens. The symbol CONSTANT is declared as
    // `entity_runtime_key = flight::Symbol::...`, so the check names the member access form rather than
    // the bare field name.
    expect(doubleCast).not.toContain('.entity_runtime_key =');

    // The read side names the member the write never sets.
    expect(
      emitIrModuleCpp(
        lower(
          'cell-read.ts',
          `${contract}
           export function get<Runtime extends object = object>(controller: Entity): Runtime & GuiControllerRuntime {
             return controller[EntityRuntimeKey] as Runtime & GuiControllerRuntime;
           }`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ).contents,
    ).toContain('controller->entity_runtime_key');

    // The sibling shape refuses, so the asymmetry is a gap in the cell path rather than a house style of
    // letting every assertion through.
    expect(
      captureBackendEmissionFailure(() =>
        emitIrModuleCpp(
          lower(
            'cell-bare-assertion.ts',
            `${contract}
             export function make<Controller extends Entity, Runtime extends GuiControllerRuntime>(
               runtime: Runtime,
             ): Controller {
               return runtime as unknown as Controller;
             }`,
          ).module,
          { runtimeProfile: 'flight-cpp' },
        ),
      ).rule,
    ).toBe('cpp-reference-assertion-without-heritage');
  });

  // The SDK's own named operations for this slot are the other spelling, and they do not remove the
  // erasure: @flighthq/entity's allocateEntity/finishEntity cast a construction to its entity type, and
  // that assertion has no emitted class-heritage path to travel. So neither spelling lowers correctly
  // today -- the cell emits silently-wrong code and the named operation refuses -- which is the answer to
  // whether a source contract removes the cell.
  it('pins the entity named operations as refused for want of an emitted heritage path', () => {
    const failure = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(
        lower(
          'entity-operations.ts',
          `export const EntityRuntimeKey = Symbol.for('EntityRuntime');
           export interface EntityRuntime { binding: object | null }
           export interface Entity { [EntityRuntimeKey]: EntityRuntime | undefined }
           export interface EntityConstruction<Type extends Entity> { [EntityRuntimeKey]: EntityRuntime | undefined }
           export function finishEntity<Type extends Entity>(out: EntityConstruction<Type>): Type {
             return out as Type;
           }`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ),
    );

    expect(failure.rule).toBe('cpp-reference-assertion-without-heritage');
    expect(failure.classification).toBe('target-runtime');
    expect(failure.message).toContain('has no heritage to cast along');
  });

  // The renderCache intersection-carrier site, bounded audit. @flighthq/render/src/renderCache.ts refuses in the
  // family "contextual C++ union conversion requires equivalent source union evidence", and the shape is exact:
  //   RenderProxyAdapter        = { adapt: (...) => boolean | null }            a bare behavioural contract
  //   RenderCacheAdapter        = Entity & RenderProxyAdapter & { cache; signals }   an INTERSECTION
  //   getRenderProxyAdapter(...): RenderProxyAdapter | null                     the declared arm
  //   setRenderProxyAdapter(..., adapter: RenderProxyAdapter | null)
  // `useRenderCache` narrows the declared arm to the intersection through its type guard and hands it back to
  // `setRenderProxyAdapter`, so a value whose C++ owner is the generated intersection struct converts into a
  // destination arm that is the bare struct -- sibling types with no base relation. The two carriers below are
  // that pair, and they are what the refusal reports.
  //
  // The rule is `cpp-contextual-union-inequivalent` and it has a SECONDARY classification, `intersectionOwnerGap`,
  // consulted only after `hasUniqueCppSemanticUnionSlotMappingCpp` succeeds; it fires when every source slot is an
  // intersection that is NOT structural-row resolvable and no target slot shares its carrier. I reproduced the
  // refusal and its carriers, but I did NOT manage to construct a case that takes that secondary branch -- the
  // intersections I built resolve as structural rows, which makes the predicate return false. Recorded plainly
  // rather than claimed: the parked name describes the branch, and what is pinned here is the refusal it belongs to.
  // Why the secondary branch above is shadowed. `hasCppDistinctIntersectionUnionOwnersCpp` needs a source slot
  // whose runtime type is an intersection that is NOT structural-row resolvable. Every shape that makes an
  // intersection non-structural -- a class-instance member, a method that cannot live in a row -- is refused
  // EARLIER by `cpp-intersection-member-shapeless`, so the union conversion never sees it. Eight constructions
  // across two passes could not reach the secondary branch; recorded as unreached-in-construction, which is not
  // the same as proven unreachable, and pinned here so the reason is visible rather than re-derived.
  it('refuses a non-structural intersection member before any union conversion sees it', () => {
    const failure = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(
        lower(
          'intersection-class-member.ts',
          `class Base { m(): number { return 1; } }
           export type Intersection = Base & { cache: string | null };
           export function set(x: { cache: string | null } | null): void { void x; }
           export function use(x: Intersection | null): void { set(x); }`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ),
    );

    // The earlier rule owns this shape, so the union rule's intersection branch is never consulted.
    expect(failure.rule).toBe('cpp-intersection-member-shapeless');
    expect(failure.classification).toBe('source-portability');
    expect(failure.rule).not.toBe('cpp-contextual-union-inequivalent');
  });

  it('refuses an intersection owner converting into a bare declared union arm', () => {
    const failure = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(
        lower(
          'render-cache-adapter.ts',
          `export const EntityRuntimeKey = Symbol.for('EntityRuntime');
           export interface EntityRuntime { binding: object | null }
           export interface Entity { [EntityRuntimeKey]: EntityRuntime | undefined }
           export type RenderProxyAdapter = { adapt(state: number): boolean | null };
           export type RenderCacheAdapter = Entity & RenderProxyAdapter & { cache: string | null };
           export function setAdapter(adapter: RenderProxyAdapter | null): void { void adapter; }
           export function use(adapter: RenderCacheAdapter | null): void { setAdapter(adapter); }`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ),
    );

    expect(failure.rule).toBe('cpp-contextual-union-inequivalent');
    expect(failure.classification).toBe('source-portability');
    expect(failure.message).toContain('contextual C++ union conversion requires equivalent source union evidence');
    // The destination names the bare contract's generated owner; the source names the intersection's.
    expect(failure.message).toContain('carriers [flight::Ref<adapt_');
    expect(failure.message).toContain('carriers [flight::Ref<entity_runtime_key_adapt_cache_');
  });

  // The rule names its own remedies, and the first one is PROVEN here rather than quoted: when both APIs name
  // the same declared owner the conversion does not exist, so the module emits. This is the only one of the
  // three the SDK could take without a runtime addition -- "keep both APIs on the same declared arm owner" --
  // and it is a source change, not a compiler change.
  it('emits once both APIs name the same declared owner', () => {
    const contents = emitIrModuleCpp(
      lower(
        'render-cache-shared-owner.ts',
        `export const EntityRuntimeKey = Symbol.for('EntityRuntime');
         export interface EntityRuntime { binding: object | null }
         export interface Entity { [EntityRuntimeKey]: EntityRuntime | undefined }
         export type RenderProxyAdapter = { adapt(state: number): boolean | null };
         export type RenderCacheAdapter = Entity & RenderProxyAdapter & { cache: string | null };
         export function setAdapter(adapter: RenderCacheAdapter | null): void { void adapter; }
         export function use(adapter: RenderCacheAdapter | null): void { setAdapter(adapter); }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;

    // One carrier on both sides: there is no conversion left to represent.
    const carriers = contents.match(/flight::Ref<entity_runtime_key_adapt_cache_[0-9a-f]+>/gu) ?? [];
    expect(carriers.length).toBeGreaterThanOrEqual(2);
    expect(new Set(carriers).size).toBe(1);
    expect(contents).toContain('set_adapter(adapter);');
  });

  // RenderProxy.ts mixed-absence finding, carried at RenderProxy.colorMatrix:
  //   colorMatrix?: readonly number[] | null;      -- optional (admits undefined) AND nullable (admits null)
  // That is three retirement states, so the carrier is a dual-sentinel variant, and the optional's ABSENT
  // state must initialise to `Undefined` rather than to `Null` or to an empty array: in TypeScript an unset
  // optional property reads as undefined. The declaration and every producer write are faithful, and the
  // control pins the initialiser because that is the one a defaulted init could silently get wrong.
  it('carries the mixed-absence optional as a dual-sentinel variant absent state', () => {
    const contents = emitIrModuleCpp(
      lower(
        'render-proxy-color-matrix.ts',
        `export interface RenderProxy {
           colorMatrix?: readonly number[] | null;
         }
         export function set(proxy: RenderProxy, mode: number): void {
           if (mode === 0) proxy.colorMatrix = [1, 0, 0, 0, 0, 0, 1];
           else if (mode === 1) proxy.colorMatrix = null;
           else proxy.colorMatrix = undefined;
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;

    // The absent state of an unset optional is Undefined, not Null and not an empty array.
    expect(contents).toContain(
      'std::variant<flight::Array<double>, flight::Null, flight::Undefined> color_matrix = std::variant<flight::Array<double>, flight::Null, flight::Undefined>{std::in_place_type<flight::Undefined>, flight::undefined};',
    );
    // Each producer writes the alternative its source names, and none of them collapses to another.
    expect(contents).toContain('std::in_place_type<flight::Array<double>>');
    expect(contents).toContain('std::in_place_type<flight::Null>, flight::null');
    expect(contents).toContain('std::in_place_type<flight::Undefined>, flight::undefined');

    // The required nullable form beside it stays a two-state optional, which is the contrast that shows the
    // optional marker is what selects the three-state carrier.
    expect(
      emitIrModuleCpp(
        lower('render-proxy-required-nullable.ts', `export interface P { colorMatrix: readonly number[] | null; }`)
          .module,
        { runtimeProfile: 'flight-cpp' },
      ).contents,
    ).toContain('std::optional<flight::Array<double>> color_matrix;');
  });

  // The consumer boundary for that carrier, and the regression this lane changed. One nullish comparison of
  // the member emits and names exactly the alternative it tests. A SECOND comparison of the same member in one
  // flow now emits too: the presence test inspects the CARRIER, so a property read asks the same storage
  // question a binding does, and short-circuit control flow supplies the narrowing. Before this the second
  // comparison projected the narrowed value, which asked an array payload for a sentinel it cannot hold, and
  // refused with `cpp-dual-sentinel-comparison-unrepresented`. The read after both guards is still sound
  // because each sentinel returns first, so the remaining payload projection cannot throw.
  it('carries dual-sentinel evidence across repeated member narrowing', () => {
    const declaration = `export interface RenderProxy { colorMatrix?: readonly number[] | null; }`;

    // One comparison: faithful, and it names exactly the alternative the source tests.
    const single = emitIrModuleCpp(
      lower(
        'render-proxy-single-test.ts',
        `${declaration}
         export function isUnset(proxy: RenderProxy): boolean { return proxy.colorMatrix === undefined; }
         export function isNull(proxy: RenderProxy): boolean { return proxy.colorMatrix === null; }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(single).toContain('std::holds_alternative<flight::Undefined>(proxy->color_matrix)');
    expect(single).toContain('std::holds_alternative<flight::Null>(proxy->color_matrix)');

    // Two comparisons of the member in one flow: emitted, with each guard a tag test on the same storage the
    // field declares, and the payload read reached only after both sentinels have returned.
    const contents = emitIrModuleCpp(
      lower(
        'render-proxy-two-tests.ts',
        `${declaration}
         export function read(proxy: RenderProxy): number {
           if (proxy.colorMatrix === undefined) return 0;
           if (proxy.colorMatrix === null) return 1;
           return proxy.colorMatrix.length;
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(contents).toContain('if (std::holds_alternative<flight::Undefined>(proxy->color_matrix))');
    expect(contents).toContain('if (std::holds_alternative<flight::Null>(proxy->color_matrix))');
    expect(contents).toContain('std::get<flight::Array<double>>(proxy->color_matrix)');
    // The narrowed read never projects through `std::get` on a payload typed as the sentinel's alternative.
    expect(contents).not.toContain('std::get<flight::Null>');

    // The loose test still excludes both sentinels, and still emits.
    expect(
      emitIrModuleCpp(
        lower(
          'render-proxy-loose-test.ts',
          `${declaration}
           export function present(proxy: RenderProxy): boolean { return proxy.colorMatrix != null; }`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ).contents,
    ).toContain(
      'std::holds_alternative<flight::Null>(proxy->color_matrix) || std::holds_alternative<flight::Undefined>(proxy->color_matrix)',
    );

    // The local-rebinding form emits the same way, so the source pattern that already worked is unchanged.
    const rebound = emitIrModuleCpp(
      lower(
        'render-proxy-rebound.ts',
        `${declaration}
         export function read(proxy: RenderProxy): number {
           const matrix = proxy.colorMatrix;
           if (matrix === undefined) return 0;
           if (matrix === null) return 1;
           return matrix.length;
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(rebound).toContain('std::holds_alternative<flight::Undefined>(optional_property)');
    expect(rebound).toContain('std::holds_alternative<flight::Null>(optional_property)');
  });

  // The @flighthq/entity guards.ts unchecked-double-assertion finding, at its two sites (lines 23 and 39 of
  // that file). Both are the SAME shape inside a Proxy `set` trap: the trap reports the write through the
  // diagnostics seam and then performs it, and the forwarding write reads
  //   (target as unknown as Record<PropertyKey, unknown>)[prop] = value;
  // -- one assertion to `unknown` and a second to an erased record, because `prop` is `string | symbol` and
  // `target` is the generic handler target, which TypeScript will not index dynamically without one.
  //
  // It is a TRUE COMPILER RESTRICTION, not a missing lowering: the rule is
  // `cpp-erased-record-assertion-unrepresented`, because the assertion hides the carrier the value actually
  // has -- here `flight::ErasedRef` -- and then names an erased record the value is not. A cast cannot restore
  // a carrier the source erased, and the compiler will not guess which one to recover.
  it('refuses the erased-record assertion that hides the source carrier', () => {
    const failure = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(
        lower(
          'guarded-entity-write.ts',
          `export function put(target: object, prop: string, value: unknown): void {
             (target as unknown as Record<PropertyKey, unknown>)[prop] = value;
           }`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ),
    );

    expect(failure.rule).toBe('cpp-erased-record-assertion-unrepresented');
    expect(failure.classification).toBe('source-portability');
    expect(failure.message).toContain('an erased assertion hides the represented source carrier');
  });

  // The assertion-free operation the lane asked about: a receiver DECLARED as the record it is written as.
  // Nothing is asserted, the key stays dynamic, and the write lowers to the record's own checked set -- so
  // the source has a spelling that needs no cast, and the refusal above is about the cast rather than about
  // a write the target cannot perform. `Reflect.set` is the other named operation, and it does not help
  // today: it is an unbound runtime symbol rather than an assertion-free lowering.
  it('emits a declared record receiver where the erased assertion was refused', () => {
    const contents = emitIrModuleCpp(
      lower(
        'declared-record-write.ts',
        `export function put(target: Record<string, unknown>, prop: string, value: unknown): void {
           target[prop] = value;
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;

    expect(contents).toContain('flight::Record<flight::String, flight::Any> target');
    expect(contents).toContain('target.set(prop, assignment_value)');
    expect(contents).not.toContain('static_cast');

    // Reflect.set is a named operation, but it is a runtime symbol before it is anything else, so it trades
    // a source-portability refusal for a target-runtime binding gap rather than removing the boundary.
    const reflect = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(
        lower(
          'reflect-set-write.ts',
          `export function put(target: object, prop: string, value: unknown): void {
             Reflect.set(target, prop, value);
           }`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ),
    );
    expect(reflect.rule).toBe('cpp-runtime-external-symbol-binding-incomplete');
    expect(reflect.classification).toBe('target-runtime');
    expect(reflect.message).toContain('missing: Reflect[value]');
  });

  // The syntax gate, spent on the shapes the two recent non-compiling-output regressions went through. Both
  // were fixed; this is what would have stopped them, and it is cheap enough to keep because it runs on two
  // fixtures rather than on the suite. A missing toolchain skips rather than fails, which is why the gate
  // reports availability as a value.
  it.skipIf(!cppSyntaxGate.available)('emits C++ the target compiler accepts for the recent regression shapes', () => {
    const syntaxCase = (label: string, body: string) => {
      const contents = emitIrModuleCpp(
        lower(
          'syntax-gate.ts',
          `export type ColorTransformFunction = (out: readonly number[], r: number) => void;
           export interface ColorLutAdjustment { readonly kind: 'lut'; readonly transform?: ColorTransformFunction }
           export interface GlScene3DRuntime { readonly count?: number | null | undefined }
           ${body}`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ).contents;
      return cppSyntaxGate.checkCppSourceSyntax(contents, label);
    };

    // A Partial row read answers std::optional, so its presence test must be the optional form; unioning an
    // explicit undefined into the read re-spelled it as a union and asked std::holds_alternative of that
    // optional, which is not a call the language has.
    const partialRow = syntaxCase(
      'partial-row-typeof',
      `export function f(operation: Readonly<{ kind: string }>): number { return typeof (operation as Readonly<Partial<ColorLutAdjustment>>).transform === 'function' ? 1 : 0; }`,
    );
    expect(partialRow.diagnostic).toBe('');
    expect(partialRow.ok).toBe(true);

    // A coalesce nested a third level deep hands its inner operand the carrier it tests, and the projection
    // it then performs has to be one the carrier supports.
    const nestedCoalesce = syntaxCase(
      'nested-coalesce',
      `export function g(a: GlScene3DRuntime, b: GlScene3DRuntime): number { return a.count ?? b.count ?? 0; }`,
    );
    expect(nestedCoalesce.diagnostic).toBe('');
    expect(nestedCoalesce.ok).toBe(true);
  });

  // Net.ts's opaque-value-domain finding. The transport's own domains are representable: NetMethod is an open
  // string that collapses to flight::String, headers is a plain record, NetBody is a CLOSED union of four
  // concrete alternatives, and NetResponseBody is arbitrary -- a union naming `unknown` is the top type in
  // TypeScript, and this compiler keeps a union's alternatives rather than collapsing them, which the Blob
  // and typeof-erasure controls already pin. What blocks the module is ownership, not shape: three host-owned
  // ambient types must each receive one externalBindings entry. Two of the three carry remediation prose;
  // ArrayBufferView is the one symbol in this set that reports bare (it has no renderMissing* sibling and is
  // absent from the ambient surface), which is reported to Foreman as its own slice rather than invented here.
  // FlightDocumentNodeSchema's opaque-value-domain finding. Its open-ended domain is
  //   export type FlightDocumentResourceLookup = Readonly<Record<string, unknown>>;
  // -- deliberately open, per its own comment: a vendor resource kind may resolve to its own value without
  // widening a closed SDK union. The domain is therefore ARBITRARY BY DECLARATION, and it is represented:
  // the alias emits as flight::Record<flight::String, flight::Any>, and the whole module emits with no
  // diagnostics inside its real 31-module neighbourhood. The pinned ledger files this module under the
  // unresolved-`auto`-placeholder family; that entry is stale, and the `auto` lines a consumer emits are
  // local deduction rather than a retained placeholder.
  //
  // The OWNERSHIP CONTRACT is the part a caller needs, and it is what makes the open domain safe to use:
  // a value read back out is recovered with a CHECKED conversion that throws when the erased value does not
  // hold the asserted type. Asserting is therefore not a reinterpretation, and the producer is not trusted
  // to have got it right.
  it('recovers a value from the open document lookup with a checked conversion', () => {
    const contents = emitIrModuleCpp(
      lower(
        'flightDocumentNodeSchema.ts',
        `export type Kind = string;
         export interface NodeAny { readonly kind: Kind }
         export interface Hero { readonly hp: number }
         export type FlightDocumentResourceLookup = Readonly<Record<string, unknown>>;
         export function read(resources: FlightDocumentResourceLookup, name: string): Hero | null {
           const value = resources[name];
           return value === undefined ? null : (value as Hero);
         }
         export function put(resources: Readonly<Record<string, unknown>>, name: string, value: unknown): void {
           (resources as Record<string, unknown>)[name] = value;
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;

    // The open domain itself: an erased record keyed by name, not a closed union and not Any.
    expect(contents).toContain('using FlightDocumentResourceLookup = flight::Record<flight::String, flight::Any>');
    // A write goes through the record's own set rather than assigning into erased storage directly.
    expect(contents).toContain('resources.set(name, assignment_value)');
    // The READ path is deliberately NOT pinned here. Its recovery asks the unwrapped value for the asserted
    // owner, but the storage the record hands back is `std::optional<flight::Any>`, so it calls object_if on
    // the optional and the target compiler rejects it: 'std::optional<flight::Any>' has no member named
    // 'object_if'. Pinning that would enshrine output that cannot compile; it is reported as its own slice.
  });

  it('classifies the net transport host bindings as one target-runtime family', () => {
    const result = lower(
      'Net.ts',
      `export type NetMethod = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE' | 'HEAD' | 'OPTIONS' | (string & {});
       export type NetResponseBody = string | unknown | ArrayBuffer | Blob | null;
       export type NetBody = string | ArrayBuffer | ArrayBufferView | null;
       export interface NetRequest {
         method: NetMethod;
         url: string;
         headers?: Readonly<Record<string, string>>;
         body?: NetBody;
       }
       export interface NetResponse {
         status: number;
         headers: Readonly<Record<string, string>>;
         body: NetResponseBody;
         ok: boolean;
       }
       export interface NetRequestOptions {
         signal?: AbortSignal;
       }`,
    );
    const failure = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(result.module, { runtimeProfile: 'flight-cpp' }),
    );

    expect(result.diagnostics).toEqual([]);
    expect(failure.rule).toBe('cpp-runtime-external-symbol-binding-incomplete');
    expect(failure.classification).toBe('target-runtime');
    // One family, three symbols: the abort lifetime identity and the two binary value carriers the body
    // unions name. Nothing here is a source-shape problem, so no source change is warranted.
    expect(failure.message).toContain('missing: AbortSignal[type], ArrayBufferView[type], Blob[type]');
    expect(failure.message).toContain('Abort cancellation handles AbortSignal are target-runtime lifetime identities');
    expect(failure.message).toContain('Blob is a host-owned immutable binary object identity');
    expect(failure.message).not.toContain('ArrayBufferView is');

    // Supplying exactly those three entries proves the finding is the binding gap and nothing else: the
    // module then emits, and every transport domain above survives as the representation it was declared as.
    const externalBindings = {
      bindings: [
        {
          headers: ['host/abort.hpp'],
          nullability: 'non-null' as const,
          ownership: 'shared' as const,
          sourceName: 'AbortSignal',
          space: 'type' as const,
          targetName: 'host::AbortSignal',
        },
        {
          headers: ['host/buffer.hpp'],
          nullability: 'non-null' as const,
          ownership: 'shared' as const,
          sourceName: 'ArrayBufferView',
          space: 'type' as const,
          targetName: 'host::ArrayBufferView',
        },
        {
          headers: ['host/blob.hpp'],
          nullability: 'non-null' as const,
          ownership: 'shared' as const,
          sourceName: 'Blob',
          space: 'type' as const,
          targetName: 'host::Blob',
        },
      ],
      schema: 'flight-cpp-external-bindings/1' as const,
    };
    const contents = emitIrModuleCpp(result.module, { externalBindings, runtimeProfile: 'flight-cpp' }).contents;

    // The open method domain is every string, not the seven seeds the source lists.
    expect(contents).toContain('using NetMethod = flight::String;');
    // A closed record keyed by the header name, and the request body kept as its own union.
    expect(contents).toContain('flight::Record<flight::String, flight::String> headers;');
    expect(contents).toContain('std::optional<NetBody> body;');
    // The erased response body keeps its alternatives rather than collapsing to a bare Any.
    expect(contents).toContain('using NetResponseBody =');
    expect(contents).toContain('flight::Any');
  });

  // AnimationChannel.ts's opaque-value-domain finding. Production producers allocate object descriptors or
  // callback carriers, cloneAnimationClip preserves the exact owner, composition uses that owner as a Map or
  // Set identity, and domain applicators recover structured binding state from it. That is an extensible
  // reference-identity protocol, not arbitrary data and not a finite union of today's target families.
  it('classifies animation targets as open typed identities rather than arbitrary payload', () => {
    const erased = emitIrModuleCpp(
      lowerPackage(
        '@flighthq/types',
        'AnimationChannel.ts',
        `export interface AnimationTrack { readonly times: readonly number[] }
         export interface AnimationChannel { track: AnimationTrack; targetRef: unknown }
         export interface AnimationTargetIndex { byTarget: Map<unknown, number> }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    const typed = emitIrModuleCpp(
      lowerPackage(
        '@flighthq/types',
        'AnimationChannel.ts',
        `export interface Entity { readonly id: number }
         export interface AnimationTrack { readonly times: readonly number[] }
         export interface AnimationTargetRef extends Entity { readonly kind: string }
         export interface AnimationChannel { track: AnimationTrack; targetRef: AnimationTargetRef }
         export interface AnimationTargetIndex { byTarget: Map<AnimationTargetRef, number> }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;

    // The erased source can represent primitive and null keys that no production target producer creates.
    expect(erased).toContain('flight::Any target_ref;');
    expect(erased).toContain('flight::Map<flight::Any, double> by_target;');

    // Closing the core boundary to one named reference keeps the kind namespace open while making the
    // channel and every identity-keyed composition table exact. No target-family union or value copy appears.
    expect(typed).toContain('struct AnimationTargetRef : public flight::ReferenceEnabled');
    expect(typed).toContain('flight::Ref<AnimationTargetRef> target_ref;');
    expect(typed).toContain('flight::Map<flight::Ref<AnimationTargetRef>, double> by_target;');
    expect(typed).not.toContain('flight::Any');
    expect(typed).not.toContain('std::variant');
    expect(typed).not.toContain('materialize_row');
  });

  // Attachment2D.ts's mixed-absence finding. Every built-in producer finishes an entity with a present
  // string-or-null name, while runtime mutation swaps attachment owners and never edits this metadata. The
  // backend can represent both source spellings; the finding asks the source to remove the unused third
  // state rather than compensating for a missing target carrier.
  it('classifies attachment names as one required nullable live cell', () => {
    const mixed = emitIrModuleCpp(
      lowerPackage(
        '@flighthq/types',
        'Attachment2D.ts',
        `export interface Entity { readonly id: number }
         export interface Attachment2D extends Entity { kind: string; name?: string | null }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    const resolved = emitIrModuleCpp(
      lowerPackage(
        '@flighthq/types',
        'Attachment2D.ts',
        `export interface Entity { readonly id: number }
         export interface Attachment2D extends Entity { kind: string; name: string | null }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;

    expect(mixed).toContain('std::variant<flight::String, flight::Null, flight::Undefined> name');
    expect(resolved).toContain('std::optional<flight::String> name;');
    for (const emitted of [mixed, resolved]) {
      expect(emitted).toContain('struct Attachment2D : public flight::ReferenceEnabled');
      expect(emitted).not.toContain('flight::Any');
      expect(emitted).not.toContain('materialize_row');
    }
  });

  // BoundingBoxAttachment2D.ts's two mixed-absence findings. Import skips never retain an attachment,
  // the only constructor writes both cells, and clone, slot mutation, and disposal preserve the exact
  // owner lifetimes. Both source spellings already have exact target carriers; the source fix removes
  // the unused omitted state rather than asking the backend to choose a sentinel.
  it('classifies bounding-box point storage as two required nullable owner cells', () => {
    const mixed = emitIrModuleCpp(
      lowerPackage(
        '@flighthq/types',
        'BoundingBoxAttachment2D.ts',
        `export interface Attachment2D { kind: string }
         export interface Skin2D { influences: Float32Array }
         export interface BoundingBoxAttachment2D extends Attachment2D {
           pointCount: number;
           skin?: Skin2D | null;
           vertices?: Float32Array | null;
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    const resolved = emitIrModuleCpp(
      lowerPackage(
        '@flighthq/types',
        'BoundingBoxAttachment2D.ts',
        `export interface Attachment2D { kind: string }
         export interface Skin2D { influences: Float32Array }
         export interface BoundingBoxAttachment2D extends Attachment2D {
           pointCount: number;
           skin: Skin2D | null;
           vertices: Float32Array | null;
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;

    expect(mixed).toContain('std::variant<flight::Ref<Skin2D>, flight::Null, flight::Undefined> skin');
    expect(mixed).toContain('std::variant<flight::Float32Array, flight::Null, flight::Undefined> vertices');
    expect(resolved).toContain('std::optional<flight::Ref<Skin2D>> skin;');
    expect(resolved).toContain('std::optional<flight::Float32Array> vertices;');
    for (const emitted of [mixed, resolved]) {
      expect(emitted).toContain('struct BoundingBoxAttachment2D : public flight::ReferenceEnabled');
      expect(emitted).not.toContain('flight::Any');
      expect(emitted).not.toContain('materialize_row');
      expect(emitted).not.toContain('static_cast');
      expect(emitted).not.toContain('reinterpret_cast');
      expect(emitted).not.toContain('externalBindings');
    }
  });

  it('separates PathAttachment2D point-owner nullability from redundant undefined states', () => {
    // Both values are compiler-owned carriers: Skin2D is a Flight entity reference and Float32Array is a
    // native typed-array value. The current optional-nullable fields preserve two sentinels, while making
    // the stored fields required nullable removes only Undefined and needs no binding or erased fallback.
    const result = lowerPackage(
      '@flighthq/types',
      'PathAttachment2D.ts',
      `export interface Entity { readonly id: number }
       export interface Attachment2D extends Entity { kind: string }
       export interface Skin2D extends Entity {
         influenceCounts: Uint16Array;
         influences: Float32Array;
       }
       export interface CurrentPathAttachment2D extends Attachment2D {
         skin?: Skin2D | null;
         vertices?: Float32Array | null;
       }
       export interface ResolvedPathAttachment2D extends Attachment2D {
         skin: Skin2D | null;
         vertices: Float32Array | null;
       }`,
    );
    const contents = emitIrModuleCpp(result.module, { runtimeProfile: 'flight-cpp' }).contents;

    expect(result.diagnostics).toEqual([]);
    expect(contents).toContain('std::variant<flight::Ref<Skin2D>, flight::Null, flight::Undefined> skin');
    expect(contents).toContain('std::variant<flight::Float32Array, flight::Null, flight::Undefined> vertices');
    expect(contents).toContain('std::optional<flight::Ref<Skin2D>> skin;');
    expect(contents).toContain('std::optional<flight::Float32Array> vertices;');
    expect(contents).toContain('struct Skin2D : public flight::ReferenceEnabled');
    expect(contents).not.toContain('flight::Any');
    expect(contents).not.toContain('static_cast');
    expect(contents).not.toContain('reinterpret_cast');
    expect(contents).not.toContain('externalBindings');
  });

  // ClippingAttachment2D.ts's two mixed-absence findings. The only current constructor writes both cells,
