  it('keeps create-factory results on the exact owner allocated by the factory', () => {
    const failure = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(
        lower(
          'material-factory-owner.ts',
          `interface SurfaceMaterial {
             alphaCutoff: number;
             readonly kind: string;
           }
           interface DepthMaterial extends SurfaceMaterial {
             far: number;
             near: number;
           }
           function createSurfaceMaterial(
             kind: string,
             opts?: Readonly<Partial<SurfaceMaterial>>,
           ): SurfaceMaterial {
             return { alphaCutoff: opts?.alphaCutoff ?? 0.5, kind };
           }
           export function createDepthMaterial(opts?: Readonly<Partial<DepthMaterial>>): DepthMaterial {
             const material = createSurfaceMaterial('DepthMaterial', opts) as DepthMaterial;
             material.far = opts?.far ?? 1;
             material.near = opts?.near ?? 0;
             return material;
           }`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ),
    );

    expect(failure).toMatchObject({
      // Source-portability rather than the runtime: the factory allocated and returned one exact owner and
      // the assertion names another, so the claim is the declaration's -- and the two remedies the message
      // leads with are source shapes (a factory generic in the owner it allocates, or a target owner
      // constructed with its own cells, which the SDK's sibling constructors already do). The runtime
      // recovery contract is the fallback the message names third, not the primary cause.
      classification: 'source-portability',
      rule: 'cpp-reference-assertion-without-heritage',
    });
    expect(failure.message).toContain('createSurfaceMaterial factory result');
    expect(failure.message).toContain('already allocated and returned');
    expect(failure.message).toContain('target-typed use');
    expect(failure.message).toContain('kind, options, or other arguments');
    expect(failure.message).toContain('generic in the exact owner it allocates and returns');
    expect(failure.message).toContain('preallocate flight::Ref<DepthMaterial>');
    expect(failure.message).toContain('named generic shared-layer initializers');
    expect(failure.message).toContain('retain flight::Ref<DepthMaterial> through target-specific writes');
    expect(failure.message).toContain('kind or registry tag is not owner validation');
    expect(failure.message).toContain('checked recovery contract');
    expect(failure.message).toContain('will not use a native pointer cast');
    expect(failure.message).toContain('reinterpret the factory result');
    expect(failure.message).toContain('copy or materialize a replacement owner');
    expect(failure.message).toContain('side storage');

    // The upstream expression this lane is about: SurfaceMaterial's own constructor asserts the
    // Material-shaped factory result to the concrete surface type. Same clause, same attribution, and the
    // control beside it shows the source shape that needs no assertion at all -- the concrete owner built
    // with its own declared cells, which is what the factory would have to allocate to be provable.
    const upstream = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(
        lower(
          'surfaceMaterial.ts',
          `interface Material { readonly kind: string }
           interface SurfaceMaterial extends Material { readonly alphaCutoff: number }
           export function createMaterial(kind: string): Material { return { kind }; }
           export function createSurfaceMaterial(kind: string): SurfaceMaterial {
             const material = createMaterial(kind) as SurfaceMaterial;
             return material;
           }`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ),
    );
    expect(upstream.rule).toBe('cpp-reference-assertion-without-heritage');
    expect(upstream.classification).toBe('source-portability');
    expect(upstream.message).toContain('createMaterial factory result');

    expect(
      emitIrModuleCpp(
        lower(
          'surfaceMaterialConstructed.ts',
          `interface Material { readonly kind: string }
           interface SurfaceMaterial extends Material { readonly alphaCutoff: number }
           export function createSurfaceMaterial(kind: string): SurfaceMaterial {
             return { kind, alphaCutoff: 0.5 };
           }`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ).contents,
    ).toContain('flight::Ref<SurfaceMaterial>');

    const accessorFailure = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(
        lower(
          'material-accessor-owner.ts',
          `interface SurfaceMaterial { readonly kind: string }
           interface DepthMaterial extends SurfaceMaterial { readonly far: number }
           function getSurfaceMaterial(): SurfaceMaterial { return { kind: 'SurfaceMaterial' }; }
           export function readDepth(): DepthMaterial {
             return getSurfaceMaterial() as DepthMaterial;
           }`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ),
    );
    expect(accessorFailure.rule).toBe('cpp-reference-assertion-without-heritage');
    expect(accessorFailure.message).toContain('Keep the exact declared owner at the API boundary');
    expect(accessorFailure.message).not.toContain('factory result');
    expect(accessorFailure.message).not.toContain('shared-layer initializers');

    const exact = emitIrModuleCpp(
      lower(
        'exact-material-factory-owner.ts',
        `interface SurfaceMaterial {
           alphaCutoff: number;
           readonly kind: string;
         }
         interface DepthMaterial extends SurfaceMaterial {
           far: number;
           near: number;
         }
         function initializeSurfaceMaterial(
           material: SurfaceMaterial,
           opts?: Readonly<Partial<SurfaceMaterial>>,
         ): void {
           material.alphaCutoff = opts?.alphaCutoff ?? 0.5;
         }
         export function createDepthMaterial(opts?: Readonly<Partial<DepthMaterial>>): DepthMaterial {
           const material: DepthMaterial = { alphaCutoff: 0.5, far: 1, kind: 'DepthMaterial', near: 0 };
           initializeSurfaceMaterial(material, opts);
           material.far = opts?.far ?? 1;
           material.near = opts?.near ?? 0;
           return material;
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(exact).toContain('return material;');
    expect(exact).not.toContain('flight::Any');
    expect(exact).not.toContain('static_pointer_cast');
    expect(exact).not.toContain('structural_ref_cast');
  });

  it('names the asserted intersection a class reference cannot be narrowed to', () => {
    // An intersection has no name of its own in C++, so the assertion's target is an anonymous owner type
    // holding the flattened members. That carrier is a generated name the author cannot act on, and it is
    // neither a base nor a derived type of the source's class, so the generic heritage sentence left the
    // reader with nothing to change. The refusal now names the spelling they wrote, says what flattening
    // did, and gives the two rewrites -- while changing nothing about what is emitted.
    const classAndInterface = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(
        lower(
          'bevel-effect-intersection.ts',
          `export class EffectBase { readonly kind: string = ''; }
           export interface BevelSpec { readonly distance: number }
           export function readDistance(effect: EffectBase): number {
             return (effect as EffectBase & BevelSpec).distance;
           }`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ),
    );
    expect(classAndInterface.rule).toBe('cpp-reference-assertion-without-heritage');
    expect(classAndInterface.classification).toBe('compiler-restriction');
    expect(classAndInterface.message).toContain('to the intersection EffectBase & BevelSpec');
    expect(classAndInterface.message).toContain('flattens the interface members of an intersection');
    expect(classAndInterface.message).toContain(
      'Declare the value as EffectBase & BevelSpec where the concrete type is known',
    );

    // The same relation between two interfaces, so the refusal is about the carrier and not about classes.
    const interfaceAndInterface = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(
        lower(
          'bevel-spec-intersection.ts',
          `export interface EffectBaseSpec { readonly kind: string }
           export interface BevelSpec { readonly distance: number }
           export function readDistance(effect: EffectBaseSpec): number {
             return (effect as EffectBaseSpec & BevelSpec).distance;
           }`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ),
    );
    expect(interfaceAndInterface.rule).toBe('cpp-reference-assertion-without-heritage');
    expect(interfaceAndInterface.message).toContain('to the intersection EffectBaseSpec & BevelSpec');

    // A readonly part makes the assertion a structural re-view instead, which is where the capability rule
    // answers -- and there the same renderer keeps the reader's spelling rather than saying "intersection".
    const readonlyPart = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(
        lower(
          'bevel-readonly-intersection.ts',
          `export class EffectBase { readonly kind: string = ''; }
           export interface BevelSpec { readonly distance: number }
           export function readDistance(effect: Readonly<EffectBase>): number {
             return (effect as Readonly<EffectBase> & BevelSpec).distance;
           }`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ),
    );
    expect(readonlyPart.rule).toBe('cpp-structural-assertion-writable-capability-unproven');
    expect(readonlyPart.classification).toBe('source-portability');
    expect(readonlyPart.message).toContain(
      'from the readonly row Readonly<EffectBase> to the writable row Readonly<EffectBase> & BevelSpec',
    );

    // The class-heritage narrowing is the sound half of the same source shape and still emits: a class
    // target has real C++ inheritance to cast along, which an intersection never does.
    const heritage = emitIrModuleCpp(
      lower(
        'bevel-class-heritage.ts',
        `export class EffectBase { readonly kind: string = ''; }
         export class BevelEffect extends EffectBase { readonly distance: number = 0; }
         export function readDistance(effect: EffectBase): number { return (effect as BevelEffect).distance; }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(heritage).toContain('std::static_pointer_cast<BevelEffect>(effect)');
    expect(heritage).not.toContain('flight::Any');
  });

