  it('refuses an assertion that would read a derived row through its base type owner', () => {
    // The shape from @flighthq/textureatlas: a local reads a base-typed reference and asserts a readonly
    // view of the DERIVED type, then reads a derived-only member. The subject is a native reference, so
    // the cast needs a structural view of it -- and a structural owner's cells are bound from the type
    // the object was first reached as. Building that view over the base binds the base's cells only, so
    // the assertion compiles and then throws `std::out_of_range` on the first derived-only read, far from
    // the assertion that asked for it. The widening proof the value-conversion lane already requires is
    // what rules it out, and the refusal names it here instead of leaving a runtime trap behind.
    const result = lower(
      'assertion-subject.ts',
      `export interface TextureSource { readonly kind: string; readonly id: number }
       export interface Bitmap extends TextureSource { readonly kind: 'bitmap'; readonly data: number[] }
       export interface Texture { readonly dimension: string; readonly source: TextureSource | null }
       export function byteSize(texture: Texture | null): number {
         if (texture === null || texture.dimension !== '2d' || texture.source === null) return 0;
         const image = texture.source;
         if (image.kind === 'bitmap') return (image as Readonly<Bitmap>).data.byteLength;
         return 0;
       }`,
    );

    // The refusal is the emission's, where the view would have been built: nothing is emitted that binds
    // a base-typed owner and then reads a derived-only cell through it.
    const failure = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(result.module, { runtimeProfile: 'flight-cpp' }),
    );
    expect(failure.rule).toBe('cpp-structural-assertion-owner-unproven');
    // Which cells the owner carries is a fact about where the object was first reached, which may be
    // anywhere in the program, so it is not the emitter's to recover: the report attributes the fix to
    // the source and names the member to declare.
    expect(failure.classification).toBe('source-portability');
    expect(failure.message).toContain('reads data, which the source type does not declare');
    expect(failure.message).toContain('Declare the source as a type that declares data');
  });

  it('refuses a structural source asserted to a derived row its owner cannot answer', () => {
    const result = lower(
      'structural-assertion-row-to-derived-row.ts',
      `interface Base { id: string }
       interface Derived extends Base { extra: number }
       export function widen(node: Readonly<Base>): Readonly<Derived> { return node as Readonly<Derived>; }`,
    );
    const failure = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(result.module, { runtimeProfile: 'flight-cpp' }),
    );

    // A source that is already a structural reference takes the same rule as a native one: the cast
    // re-views the owner the object was first reached as, so an asserted row that reaches past that
    // owner's cells is refused at both doors rather than emitted as a read that finds no cell.
    expect(failure.rule).toBe('cpp-structural-assertion-owner-unproven');
    expect(failure.classification).toBe('source-portability');
    expect(failure.message).toContain('reads extra, which the source type does not declare');
  });

  it('attributes a kind-registered callback that erases its concrete command owner to the source boundary', () => {
    const commandTypes = `interface Command { readonly kind: string; readonly label: string }
       interface CompositeCommand extends Command { readonly children: readonly Command[] }`;
    const erased = lower(
      'command-binding-erased-owner.ts',
      `${commandTypes}
       interface CommandBinding { readonly execute: (command: Readonly<Command>) => void }
       export function compositeCommandBinding(): CommandBinding {
         return {
           execute: (command) => {
             const children = (command as Readonly<CompositeCommand>).children;
             if (children.length === 0) return;
           },
         };
       }`,
    );
    const failure = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(erased.module, { runtimeProfile: 'flight-cpp' }),
    );

    // The registry selects the callback beside the value, but its parameter has already retained only the
    // Command owner. That separate key does not prove cells for the derived command.
    expect(erased.diagnostics).toEqual([]);
    expect(failure.rule).toBe('cpp-structural-assertion-owner-unproven');
    expect(failure.classification).toBe('source-portability');
    expect(failure.message).toContain('reads children, which the source type does not declare');
    expect(failure.message).toContain('Preserve the concrete owner in the source type');
    expect(failure.message).toContain('make an intentionally erased registry validate and recover that owner');
    expect(failure.message).toContain('a tag or registry key carried beside the value does not prove');

    // Keeping the exact command owner at the callback/API boundary is already represented and reads the
    // existing row directly; it needs no cast, replacement row, or side storage.
    const exact = emitIrModuleCpp(
      lower(
        'command-binding-exact-owner.ts',
        `${commandTypes}
         export function childCount(command: Readonly<CompositeCommand>): number { return command.children.length; }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(exact).toContain('flight::row_get<flight::RowKey<"children">>(command)');
    expect(exact).not.toContain('structural_ref_cast');
    expect(exact).not.toContain('materialize');
    expect(exact).not.toContain('make_ref');

    // The source-level rewrite available to the erased callback is to make the capability part of its
    // declared owner: add `readonly children?: readonly Command[]` to Command, remove the assertion, and
    // guard absence. That binds a real cell on the base owner instead of asking the compiler to invent one.
    const declaredCapability = emitIrModuleCpp(
      lower(
        'command-binding-declared-capability.ts',
        `interface Command {
           readonly children?: readonly Command[];
           readonly kind: string;
           readonly label: string;
         }
         interface CommandBinding { readonly execute: (command: Readonly<Command>) => void }
         export function compositeCommandBinding(): CommandBinding {
           return {
             execute: (command) => {
               const children = command.children;
               if (children === undefined || children.length === 0) return;
             },
           };
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(declaredCapability).toContain('std::optional<flight::Array<flight::Ref<Command>>> children;');
    expect(declaredCapability).toContain('flight::named_properties(command).get(flight::String("children"))');
    expect(declaredCapability).toContain('children.has_value()');
    expect(declaredCapability).toContain('children.size()');
    expect(declaredCapability).not.toContain('structural_ref_cast');
    expect(declaredCapability).not.toContain('materialize');
    expect(declaredCapability).not.toContain('make_ref<Command>');
  });

